# Policy types (Phase 6)
_V8_POLICY_TYPES = [
    "energy_policy","climate_adaptation","infrastructure_investment",
    "migration_policy","economic_intervention","strategic_reserves",
]


def _v8_load(path_rel: str) -> dict:
    p = GRDF_DIR / path_rel
    if p.exists():
        try:
            return json.loads(p.read_text())
        except Exception:
            return {}
    return {}


# ── Phase 1: Decision Candidate Engine ───────────────────────────────────

def _build_v8_candidates(iso2: str, snap: dict) -> dict:
    """
    Phase 1: Generate strategic response actions for this country's risk cluster.
    Filters action catalogue to those most relevant to dominant domains.
    """
    dom_s   = _get_domain_scores(iso2, snap)
    warn_d  = _v8_load(f"v7_warning_score_{iso2}.json")
    alert_d = _v8_load(f"v7_alerts_{iso2}.json")

    ews        = float(warn_d.get("early_warning_score", 40))
    alert_lvl  = alert_d.get("alert_level","GREEN")
    alert_ord  = {"GREEN":0,"YELLOW":1,"ORANGE":2,"RED":3,"BLACK":4}
    urgency    = alert_ord.get(alert_lvl, 0)

    # Find top-2 domains by score
    top_domains = sorted(dom_s.items(), key=lambda x: -x[1].get("score",0))[:3]
    top_dom_ids  = {d for d,_ in top_domains}

    candidates = []
    for act in _V8_ACTION_CATALOGUE:
        # Relevance: action domain matches a top-risk domain
        dom_match = act["domain"] in top_dom_ids or urgency >= 3
        if not dom_match:
            continue
        # Urgency scaling: high alert -> favour fast actions
        urgency_bonus = urgency * 0.05
        effective_feas = min(1.0, act["feas"] + urgency_bonus)
        candidates.append({
            **act,
            "feasibility_adjusted": round(effective_feas, 3),
            "urgency_context":      alert_lvl,
            "ews_context":          round(ews),
        })

    # Always include emergency response if alert >= ORANGE
    if urgency >= 2 and not any(c["id"]=="ACT-07" for c in candidates):
        act = next(a for a in _V8_ACTION_CATALOGUE if a["id"]=="ACT-07")
        candidates.append({**act,"feasibility_adjusted":act["feas"],"urgency_context":alert_lvl,"ews_context":round(ews)})

    return {
        "country":      iso2,
        "country_name": snap.get("country_name", iso2),
        "date":         TODAY,
        "grdf_version": "8.0",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "n_candidates": len(candidates),
        "candidates":   candidates,
        "dominant_domains": [d for d,_ in top_domains],
        "alert_level":  alert_lvl,
        "ews":          round(ews),
    }


# ── Phase 2: Decision Effectiveness Score ────────────────────────────────

def _des(rr: float, rg: float, feas: float, conf: float) -> float:
    """
    DES = risk_reduction*0.40 + resilience_gain*0.30 + feasibility*0.20 + confidence*0.10
    All inputs 0-1, output 0-100.
    """
    return max(0, min(100, round((rr*0.40 + rg*0.30 + feas*0.20 + conf*0.10) * 100)))


def _des_grade(score: float) -> str:
    if score >= 75: return "strategic"
    if score >= 50: return "effective"
    if score >= 25: return "moderate"
    return "ineffective"


def _build_v8_decision_scores(iso2: str, snap: dict, cands: dict) -> dict:
    """Phase 2: score each candidate action with DES formula."""
    fc_d     = _v8_load(f"v3_forecast_{iso2}.json")
    conf_raw = float((fc_d.get("horizons") or {}).get("30d", {}).get("confidence", 0.65) or 0.65)

    scored = []
    for act in cands.get("candidates", []):
        des = _des(act["rr"], act["rg"],
                   act.get("feasibility_adjusted", act["feas"]), conf_raw)
        scored.append({
            "id":           act["id"],
            "label":        act["label"],
            "domain":       act["domain"],
            "des":          des,
            "des_grade":    _des_grade(des),
            "risk_reduction":   round(act["rr"] * 100),
            "resilience_gain":  round(act["rg"] * 100),
            "feasibility":      round(act.get("feasibility_adjusted", act["feas"]) * 100),
            "confidence":       round(conf_raw * 100),
        })
    scored.sort(key=lambda x: -x["des"])

    return {
        "country":         iso2,
        "country_name":    snap.get("country_name", iso2),
        "date":            TODAY,
        "grdf_version":    "8.0",
        "generated_at":    datetime.now(timezone.utc).isoformat(),
        "top_des":         scored[0]["des"] if scored else 0,
        "top_action":      scored[0]["label"] if scored else "none",
        "scored_actions":  scored,
        "avg_des":         round(sum(s["des"] for s in scored)/max(1,len(scored)),1),
    }


# ── Phase 3: Cost-Benefit Engine ─────────────────────────────────────────

def _cbi(benefit: float, cost: float) -> float:
    """CBI = expected_benefit / implementation_cost  (normalised, 0..5+)."""
    return round(benefit / max(1, cost), 3)


def _cbi_grade(cbi: float) -> str:
    if cbi >= 2.0: return "low_cost_high_impact"
    if cbi >= 1.0: return "medium_cost_high_impact"
    return "high_cost_strategic"


def _build_v8_cost_benefit(iso2: str, snap: dict, cands: dict, scores: dict) -> dict:
    """Phase 3: CBI = expected_benefit / implementation_cost."""
    scored_map = {s["id"]: s for s in scores.get("scored_actions", [])}
    cb_list = []
    for act in cands.get("candidates", []):
        s = scored_map.get(act["id"], {})
        benefit = float(s.get("des", 50))            # DES as proxy for benefit (0-100)
        cost    = float(act.get("cost_idx", 50))     # cost_idx 1-100
        cbi     = _cbi(benefit, cost)
        cb_list.append({
            "id":            act["id"],
            "label":         act["label"],
            "cbi":           cbi,
            "cbi_grade":     _cbi_grade(cbi),
            "expected_benefit": round(benefit),
            "implementation_cost": round(cost),
            "speed_days":    act.get("speed", 180),
        })
    cb_list.sort(key=lambda x: -x["cbi"])

    return {
        "country":      iso2,
        "country_name": snap.get("country_name", iso2),
        "date":         TODAY,
        "grdf_version": "8.0",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "best_cbi_action": cb_list[0]["label"] if cb_list else "none",
        "best_cbi":        cb_list[0]["cbi"]   if cb_list else 0,
        "cost_benefit":    cb_list,
    }


# ── Phase 4: Strategic Response Ranking ──────────────────────────────────

def _rank_score(des: float, cbi: float, urgency_norm: float) -> float:
    """rank_score = DES*0.50 + CBI_norm*0.30 + urgency*0.20"""
    cbi_norm = min(100, round(cbi * 20))    # CBI to 0-100 (CBI 5 = 100)
    return max(0, min(100, round(des*0.50 + cbi_norm*0.30 + urgency_norm*0.20)))


def _build_v8_response_rank(iso2: str, snap: dict,
                              scores: dict, cb: dict, ews: float) -> dict:
    """Phase 4: rank_score = DES*0.50 + CBI*0.30 + urgency*0.20"""
    urgency_norm = min(100, round(ews))
    scored_map = {s["id"]: s for s in scores.get("scored_actions", [])}
    cbi_map    = {c["id"]: c for c in cb.get("cost_benefit", [])}
    ids        = list(scored_map.keys())

    ranked = []
    for aid in ids:
        s   = scored_map[aid]
        c   = cbi_map.get(aid, {})
        rs  = _rank_score(s["des"], c.get("cbi", 1.0), urgency_norm)
        ranked.append({
            "rank":         0,   # set below
            "id":           aid,
            "label":        s["label"],
            "domain":       s["domain"],
            "rank_score":   rs,
            "des":          s["des"],
            "des_grade":    s["des_grade"],
            "cbi":          c.get("cbi", 0),
            "speed_days":   c.get("speed_days", 180),
        })
    ranked.sort(key=lambda x: -x["rank_score"])
    for i, r in enumerate(ranked, 1):
        r["rank"] = i

    return {
        "country":      iso2,
        "country_name": snap.get("country_name", iso2),
        "date":         TODAY,
        "grdf_version": "8.0",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "top10":        ranked[:10],
        "top_action":   ranked[0]["label"] if ranked else "none",
        "urgency_norm": urgency_norm,
    }


# ── Phase 5: Counterfactual Simulation ───────────────────────────────────

def _project_cf(base: float, delta: float, years: int,
                act_taken: bool, rr: float) -> dict:
    """
    Phase 5: simulate one horizon with vs without action.
    With action: risk_reduction dampens the projected score.
    Without action: unconstrained trend propagation.
    """
    damp   = 1.0 / (1.0 + years / 5.0)
    drift  = delta * damp * 365 / 7
    raw_no = max(5, min(97, round((base + drift)))  )
    raw_ac = max(5, min(97, round((base + drift) * (1.0 - rr * 0.5)))) if act_taken else raw_no
    return {
        "with_action":    raw_ac,
        "without_action": raw_no,
        "risk_reduction": max(0, raw_no - raw_ac),
        "pct_reduction":  round((raw_no - raw_ac) / max(1, raw_no) * 100, 1),
    }


def _build_v8_counterfactual(iso2: str, snap: dict, top_action: dict) -> dict:
    """Phase 5: counterfactual for top-ranked action across 1/3/5/10 year horizons."""
    base  = int(snap.get("risk_score", 50) or 50)
    delta = float(snap.get("delta", 0) or 0)
    rr    = float(top_action.get("rr", 0.60))

    horizons = {}
    for yr in [1, 3, 5, 10]:
        horizons[f"{yr}yr"] = _project_cf(base, delta, yr, True, rr)

    net_10yr = horizons["10yr"]["risk_reduction"]
    return {
        "country":         iso2,
        "country_name":    snap.get("country_name", iso2),
        "date":            TODAY,
        "grdf_version":    "8.0",
        "generated_at":    datetime.now(timezone.utc).isoformat(),
        "action_taken":    top_action.get("label","N/A"),
        "action_id":       top_action.get("id","?"),
        "base_score":      base,
        "mean_delta":      round(delta, 2),
        "risk_reduction_coeff": round(rr, 3),
        "horizons":        horizons,
        "net_10yr_reduction": net_10yr,
        "verdict":         ("high_impact" if net_10yr >= 15 else
                            "moderate_impact" if net_10yr >= 5 else
                            "low_impact"),
    }


# ── Phase 6: Policy Impact Simulator ─────────────────────────────────────

def _policy_impact(policy: str, base: float, delta: float,
                    dom_s: dict) -> dict:
    """
    Phase 6: estimate impact of each policy model on GRI and domains.
    Each policy targets specific domains with a risk-reduction multiplier.
    """
    _policy_domain_map: dict[str, tuple[str, float]] = {
        "energy_policy":              ("energy",         0.55),
        "climate_adaptation":         ("climate",        0.62),
        "infrastructure_investment":  ("infrastructure", 0.58),
        "migration_policy":           ("social",         0.40),
        "economic_intervention":      ("economic",       0.52),
        "strategic_reserves":         ("energy",         0.48),
    }
    dom_key, rr_coeff = _policy_domain_map.get(policy, ("economic", 0.40))
    dom_score  = dom_s.get(dom_key, {}).get("score", 50)
    new_dom_sc = max(5, round(dom_score * (1.0 - rr_coeff)))
    gri_delta  = round((dom_score - new_dom_sc) * 0.15)   # partial GRI lift

    return {
        "policy":            policy,
        "target_domain":     dom_key,
        "current_domain_score": dom_score,
        "post_policy_score": new_dom_sc,
        "domain_reduction":  dom_score - new_dom_sc,
        "estimated_gri_lift":gri_delta,
        "implementation_time_days": {"energy_policy":365,"climate_adaptation":730,
            "infrastructure_investment":540,"migration_policy":270,
            "economic_intervention":180,"strategic_reserves":365}.get(policy,365),
    }


def _build_v8_policy_impacts(iso2: str, snap: dict) -> dict:
    """Phase 6: simulate all policy types."""
    dom_s  = _get_domain_scores(iso2, snap)
    base   = int(snap.get("risk_score", 50) or 50)
    delta  = float(snap.get("delta", 0) or 0)

    policies = [_policy_impact(p, base, delta, dom_s) for p in _V8_POLICY_TYPES]
    policies.sort(key=lambda x: -x["estimated_gri_lift"])

    return {
        "country":      iso2,
        "country_name": snap.get("country_name", iso2),
        "date":         TODAY,
        "grdf_version": "8.0",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "base_gri":     base,
        "policies":     policies,
        "best_policy":  policies[0]["policy"] if policies else "none",
        "max_gri_lift": policies[0]["estimated_gri_lift"] if policies else 0,
    }


# ── Phase 7: Strategic Playbook Engine ───────────────────────────────────

def _build_v8_playbook(iso2: str, snap: dict, ranked: dict) -> dict:
    """
    Phase 7: Map ranked actions to playbook timelines:
    Immediate / 90-day / 1-year / 3-year / 10-year
    """
    def _bucket(speed_days):
        if speed_days <= 14:   return "immediate"
        if speed_days <= 90:   return "90_day"
        if speed_days <= 365:  return "1_year"
        if speed_days <= 1095: return "3_year"
        return "10_year"

    playbook: dict[str, list] = {
        "immediate":[], "90_day":[], "1_year":[], "3_year":[], "10_year":[]
    }
    for r in (ranked.get("top10") or []):
        bucket = _bucket(r.get("speed_days", 180))
        playbook[bucket].append({
            "rank":         r["rank"],
            "id":           r["id"],
            "label":        r["label"],
            "rank_score":   r["rank_score"],
            "des":          r["des"],
            "speed_days":   r.get("speed_days", 180),
        })

    return {
        "country":      iso2,
        "country_name": snap.get("country_name", iso2),
        "date":         TODAY,
        "grdf_version": "8.0",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "playbook":     playbook,
        "priority_bucket": "immediate" if playbook["immediate"] else
                           "90_day"    if playbook["90_day"]    else "1_year",
    }


# ── Phase 8: Autonomous Mitigation Engine ────────────────────────────────

def _ms(effectiveness: float, speed: float, feas: float, rg: float) -> float:
    """
    MS = effectiveness*0.40 + speed*0.20 + feasibility*0.20 + resilience_gain*0.20
    All 0-1 inputs, output 0-100.
    """
    return max(0, min(100, round((effectiveness*0.40 + speed*0.20 + feas*0.20 + rg*0.20) * 100)))


def _build_v8_mitigation(iso2: str, snap: dict, cands: dict) -> dict:
    """Phase 8: Mitigation Score for every candidate action."""
    mitigations = []
    for act in cands.get("candidates", []):
        # Speed normalised: 7d action = speed 1.0, 730d = 0.05
        speed_norm = max(0.05, min(1.0, 1.0 - act.get("speed", 180) / 730.0))
        ms = _ms(act["rr"], speed_norm, act.get("feasibility_adjusted", act["feas"]), act["rg"])
        mitigations.append({
            "id":           act["id"],
            "label":        act["label"],
            "domain":       act["domain"],
            "mitigation_score": ms,
            "ms_grade":     ("critical" if ms >= 75 else "high" if ms >= 50 else
                             "moderate" if ms >= 25 else "low"),
            "effectiveness":round(act["rr"] * 100),
            "speed_norm":   round(speed_norm, 3),
            "speed_days":   act.get("speed", 180),
        })
    mitigations.sort(key=lambda x: -x["mitigation_score"])

    return {
        "country":        iso2,
        "country_name":   snap.get("country_name", iso2),
        "date":           TODAY,
        "grdf_version":   "8.0",
        "generated_at":   datetime.now(timezone.utc).isoformat(),
        "top_mitigation": mitigations[0]["label"] if mitigations else "none",
        "top_ms":         mitigations[0]["mitigation_score"] if mitigations else 0,
        "mitigations":    mitigations,
        "avg_ms":         round(sum(m["mitigation_score"] for m in mitigations)/max(1,len(mitigations)),1),
    }


# ── Phase 9: Decision Confidence Engine ──────────────────────────────────

def _dc(fc_conf: float, data_quality: float, model_agreement: float) -> float:
    """
    DC = forecast_confidence*0.50 + data_quality*0.30 + model_agreement*0.20
    All 0-1, output 0-100.
    """
    return max(0, min(100, round((fc_conf*0.50 + data_quality*0.30 + model_agreement*0.20) * 100)))


def _build_v8_decision_confidence(iso2: str, snap: dict) -> dict:
    """Phase 9: Confidence in the decision recommendation."""
    fc_d     = _v8_load(f"v3_forecast_{iso2}.json")
    expl_d   = _v8_load(f"v2_explain_{iso2}.json")
    mc_d     = _v8_load(f"v6_montecarlo_{iso2}.json")

    # Forecast confidence from V3
    fc_conf_raw = float((fc_d.get("horizons") or {}).get("30d", {}).get("confidence", 0.65) or 0.65)

    # Data quality proxy: coverage of V1-V7 artefacts
    artefacts  = [f"v3_forecast_{iso2}.json","v5_signals_{iso2}.json",
                   f"v6_digital_twin_{iso2}.json","v7_warning_score_{iso2}.json"]
    present    = sum(1 for a in artefacts if (GRDF_DIR / a).exists())
    dq         = present / len(artefacts)

    # Model agreement: MC p50 vs forecast p50 closeness
    mc_p50 = float((mc_d.get("horizons") or {}).get("5yr", {}).get("p50", 50) or 50)
    fc_365 = float((fc_d.get("horizons") or {}).get("365d", {}).get("score", 50) or 50)
    agreement  = max(0.0, 1.0 - abs(mc_p50 - fc_365) / 50.0)

    dc_score = _dc(fc_conf_raw, dq, agreement)

    return {
        "country":          iso2,
        "country_name":     snap.get("country_name", iso2),
        "date":             TODAY,
        "grdf_version":     "8.0",
        "generated_at":     datetime.now(timezone.utc).isoformat(),
        "decision_confidence": dc_score,
        "dc_grade":         ("high" if dc_score >= 70 else "moderate" if dc_score >= 40 else "low"),
        "components": {
            "forecast_confidence": round(fc_conf_raw * 100),
            "data_quality":        round(dq * 100),
            "model_agreement":     round(agreement * 100),
        },
    }


# ── Phase 10: Strategic Decision Dashboard ────────────────────────────────

def _save_v8_dashboard(snapshots: list,
                        all_ranked: list, all_cf: list,
                        all_mit: list,   all_dc: list,
                        all_policy: list, all_pb: list) -> None:
    """Phase 10: 10-widget Strategic Decision Dashboard."""
    now_ts = datetime.now(timezone.utc).isoformat()

    # W1: Top Decisions (highest rank_score across all countries)
    top_decisions = sorted(
        [{"country":r["country"],"action":r["top_action"],"rank_score":(r["top10"][0]["rank_score"] if r.get("top10") else 0)}
         for r in all_ranked],
        key=lambda x: -x["rank_score"])[:10]

    # W2: Top Risk Reductions (highest net_10yr_reduction)
    top_risk_reductions = sorted(
        [{"country":c["country"],"action":c["action_taken"],"net_10yr":c["net_10yr_reduction"]}
         for c in all_cf],
        key=lambda x: -x["net_10yr"])[:10]

    # W3: Cost vs Impact (best CBI)
    cost_impact = []
    for r in all_ranked:
        top10 = r.get("top10", [])
        if top10:
            best = max(top10, key=lambda x: x.get("cbi",0))
            cost_impact.append({"country":r["country"],"action":best["label"],"cbi":best.get("cbi",0),"des":best["des"]})
    cost_impact.sort(key=lambda x: -x["cbi"])

    # W4: Resilience Gains (avg DES resilience_gain)
    resilience_gains = sorted(
        [{"country":r["country"],"avg_des":r.get("avg_des",0)} for r in
         [_v8_load(f"v8_decision_score_{s['country']}.json") for s in snapshots]
         if r and "avg_des" in r],
        key=lambda x: -x["avg_des"])[:10]

    # W5: Strategic Priorities (top immediate + 90d actions globally)
    strategic_priorities = []
    for pb in all_pb:
        for act in (pb.get("playbook",{}).get("immediate",[]) + pb.get("playbook",{}).get("90_day",[]))[:2]:
            strategic_priorities.append({"country":pb["country"],"action":act["label"],"rank_score":act["rank_score"],"bucket":pb["priority_bucket"]})
    strategic_priorities.sort(key=lambda x: -x["rank_score"])

    # W6: Policy Simulator summary
    policy_summary = sorted(
        [{"country":p["country"],"best_policy":p["best_policy"],"gri_lift":p["max_gri_lift"]}
         for p in all_policy],
        key=lambda x: -x["gri_lift"])[:10]

    # W7: Counterfactual results
    cf_summary = sorted(
        [{"country":c["country"],"action":c["action_taken"],"verdict":c["verdict"],"net_10yr":c["net_10yr_reduction"]}
         for c in all_cf],
        key=lambda x: -x["net_10yr"])[:10]

    # W8: Decision Confidence ranking
    dc_ranking = sorted(
        [{"country":d["country"],"dc":d["decision_confidence"],"grade":d["dc_grade"]}
         for d in all_dc],
        key=lambda x: -x["dc"])[:10]

    # W9: National Playbooks (per country priority)
    national_playbooks = [
        {"country":pb["country"],"priority_bucket":pb["priority_bucket"],
         "immediate_n":len(pb.get("playbook",{}).get("immediate",[])),
         "top_immediate":pb.get("playbook",{}).get("immediate",[{}])[0].get("label","none")}
        for pb in all_pb
    ]

    # W10: Global Decision Atlas (per-country best action)
    global_atlas = {r["country"]: {
        "top_action":   r["top_action"],
        "rank_score":   r["top10"][0]["rank_score"] if r.get("top10") else 0,
    } for r in all_ranked}

    # Summary stats
    avg_dc  = round(sum(d["decision_confidence"] for d in all_dc) / max(1,len(all_dc)),1)
    avg_mit = round(sum(m["avg_ms"]              for m in all_mit) / max(1,len(all_mit)),1)

    with open(GRDF_DIR / "v8_dashboard.json","w") as f:
        json.dump({
            "grdf_version":        "8.0",
            "date":                TODAY,
            "generated_at":        now_ts,
            "summary": {
                "avg_decision_confidence": avg_dc,
                "avg_mitigation_score":    avg_mit,
                "countries_with_immediate_action": sum(
                    1 for pb in all_pb if pb.get("playbook",{}).get("immediate")),
            },
            "top_decisions":           top_decisions,
            "top_risk_reductions":     top_risk_reductions,
            "cost_vs_impact":          cost_impact[:10],
            "resilience_gains":        resilience_gains,
            "strategic_priorities":    strategic_priorities[:10],
            "policy_simulator":        policy_summary,
            "counterfactual_results":  cf_summary,
            "decision_confidence":     dc_ranking,
            "national_playbooks":      national_playbooks,
            "global_decision_atlas":   global_atlas,
        }, f, ensure_ascii=False, indent=2)
    print("[GRDF-V8] Phase 10: Strategic Decision Dashboard", file=sys.stderr)


# ── V8 Orchestrator ───────────────────────────────────────────────────────

def save_grdf_v8(snapshots: list) -> None:
    """
    GRDF V8 -- Strategic Decision Intelligence.
    Dependency: V1->V2->V3->V4->V5->V6->V7->V8
    Reads: v1..v7 outputs.  Writes: v8_* only.
    V1/V2/V3/V4/V5/V6/V7 NEVER modified.
    """
    GRDF_DIR.mkdir(parents=True, exist_ok=True)

    all_ranked:   list[dict] = []
    all_cf:       list[dict] = []
    all_mit:      list[dict] = []
    all_dc:       list[dict] = []
    all_policy:   list[dict] = []
    all_pb:       list[dict] = []

    for snap in snapshots:
        iso2 = snap["country"]
        try:
            # Phase 1
            cands = _build_v8_candidates(iso2, snap)
            with open(GRDF_DIR / f"v8_decision_candidates_{iso2}.json","w") as f:
                json.dump(cands, f, ensure_ascii=False, indent=2)

            # Phase 2
            scores = _build_v8_decision_scores(iso2, snap, cands)
            with open(GRDF_DIR / f"v8_decision_score_{iso2}.json","w") as f:
                json.dump(scores, f, ensure_ascii=False, indent=2)

            # Phase 3
            cb = _build_v8_cost_benefit(iso2, snap, cands, scores)
            with open(GRDF_DIR / f"v8_cost_benefit_{iso2}.json","w") as f:
                json.dump(cb, f, ensure_ascii=False, indent=2)

            # Phase 4 (needs EWS from V7)
            warn_d  = _v8_load(f"v7_warning_score_{iso2}.json")
            ews     = float(warn_d.get("early_warning_score", 40))
            ranked  = _build_v8_response_rank(iso2, snap, scores, cb, ews)
            ranked["country"] = iso2
            with open(GRDF_DIR / f"v8_response_rank_{iso2}.json","w") as f:
                json.dump(ranked, f, ensure_ascii=False, indent=2)
            all_ranked.append(ranked)

            # Phase 5
            top_act = next((a for a in _V8_ACTION_CATALOGUE if a["id"] == (ranked.get("top10") or [{}])[0].get("id","ACT-01")), _V8_ACTION_CATALOGUE[0])
            cf = _build_v8_counterfactual(iso2, snap, top_act)
            with open(GRDF_DIR / f"v8_counterfactual_{iso2}.json","w") as f:
                json.dump(cf, f, ensure_ascii=False, indent=2)
            all_cf.append(cf)

            # Phase 6
            pol = _build_v8_policy_impacts(iso2, snap)
            with open(GRDF_DIR / f"v8_policy_impacts_{iso2}.json","w") as f:
                json.dump(pol, f, ensure_ascii=False, indent=2)
            all_policy.append(pol)

            # Phase 7
            pb = _build_v8_playbook(iso2, snap, ranked)
            with open(GRDF_DIR / f"v8_playbook_{iso2}.json","w") as f:
                json.dump(pb, f, ensure_ascii=False, indent=2)
            all_pb.append(pb)

            # Phase 8
            mit = _build_v8_mitigation(iso2, snap, cands)
            with open(GRDF_DIR / f"v8_mitigation_{iso2}.json","w") as f:
                json.dump(mit, f, ensure_ascii=False, indent=2)
            all_mit.append(mit)

            # Phase 9
            dc = _build_v8_decision_confidence(iso2, snap)
            with open(GRDF_DIR / f"v8_decision_confidence_{iso2}.json","w") as f:
                json.dump(dc, f, ensure_ascii=False, indent=2)
            all_dc.append(dc)

        except Exception as e:
            print(f"[GRDF-V8] {iso2}: FAILED -- {e}", file=sys.stderr)

    # Phase 10: dashboard
    _save_v8_dashboard(snapshots, all_ranked, all_cf, all_mit,
                       all_dc, all_policy, all_pb)

    print(f"[GRDF-V8] All 10 phases complete. {len(all_ranked)} countries processed.", file=sys.stderr)


# =========================================================================
# GLOBAL RISK DATA FABRIC V9 -- Autonomous Strategic Intelligence
#
# "What must be done automatically right now, given all scenarios?"
#
# Phase 1:  Global Action Candidates     -> v9_action_candidates_{CC}.json
# Phase 2:  Autonomous Priority Score    -> v9_priority_score_{CC}.json
# Phase 3:  Resource Allocation Engine   -> v9_resource_allocation_{CC}.json
# Phase 4:  Multi-Risk Optimization      -> v9_multi_risk_plan_{CC}.json
# Phase 5:  Autonomous Escalation Logic  -> v9_escalation_{CC}.json
# Phase 6:  Dynamic Playbook Generator   -> v9_dynamic_playbook_{CC}.json
# Phase 7:  Autonomous Scenario Switching-> v9_active_scenario_{CC}.json
# Phase 8:  Strategic Coordination Score -> v9_coordination_{CC}.json
# Phase 9:  Autonomous Confidence        -> v9_autonomous_confidence_{CC}.json
# Phase 10: Global Autonomous Dashboard  -> v9_dashboard.json
#
# Reads: v1..v8 outputs (read-only).
# Writes: v9_* only.  V1-V8 NEVER modified.
# =========================================================================

# APS thresholds (Phase 2)
_V9_APS_GRADES = [(80,"critical"),(60,"high"),(40,"moderate"),(0,"low")]

# Escalation levels (Phase 5)
_V9_ESC_LEVELS = [(85,"BLACK"),(70,"RED"),(55,"ORANGE"),(35,"YELLOW"),(0,"GREEN")]

# Resource types (Phase 3)
_V9_RESOURCE_TYPES = ["budget","time","personnel","infrastructure","logistics"]

# Dynamic playbook buckets (Phase 6)
_V9_PLAYBOOK_BUCKETS = ["24h","7d","30d","90d","1yr"]

# Scenario switch triggers (Phase 7)
_V9_SWITCH_TRIGGERS = [
    "probability_change","tte_change","new_risk","cascade_effect"]


def _v9_load(path_rel: str) -> dict:
    p = GRDF_DIR / path_rel
    if p.exists():
        try:
            return json.loads(p.read_text())
        except Exception:
            return {}
    return {}


def _v9_aps_grade(score: float) -> str:
    for thr, grade in _V9_APS_GRADES:
        if score >= thr:
            return grade
    return "low"


def _v9_esc_level(score: float) -> str:
    for thr, level in _V9_ESC_LEVELS:
        if score >= thr:
            return level
    return "GREEN"


# ── Phase 1: Global Action Candidates ────────────────────────────────────

def _build_v9_action_candidates(iso2: str, snap: dict) -> dict:
    """
    Phase 1: Pull top actions from V8 ranked responses, playbook, and
    mitigation scores to form the V9 global action pool for this country.
    """
    rank_d  = _v9_load(f"v8_response_rank_{iso2}.json")
    pb_d    = _v9_load(f"v8_playbook_{iso2}.json")
    mit_d   = _v9_load(f"v8_mitigation_{iso2}.json")
    dc_d    = _v9_load(f"v8_decision_confidence_{iso2}.json")

    # V8 top-10 ranked actions
    v8_top  = (rank_d.get("top10") or [])[:10]
    # V8 immediate playbook actions
    imm     = (pb_d.get("playbook") or {}).get("immediate", [])[:3]
    # V8 top-3 mitigations
    mit_top = (mit_d.get("mitigations") or [])[:3]

    # Merge and deduplicate by action id
    seen_ids: set = set()
    candidates  = []
    for act in v8_top + imm + mit_top:
        aid = act.get("id","?")
        if aid in seen_ids:
            continue
        seen_ids.add(aid)
        candidates.append({
            "id":           aid,
            "label":        act.get("label","?"),
            "domain":       act.get("domain","?"),
            "rank_score":   act.get("rank_score", act.get("mitigation_score", 50)),
            "des":          act.get("des", act.get("mitigation_score", 50)),
            "speed_days":   act.get("speed_days", act.get("speed", 180)),
            "source":       "v8_rank" if act in v8_top else "v8_playbook" if act in imm else "v8_mitigation",
        })

    dc_score = float(dc_d.get("decision_confidence", 60))

    return {
        "country":          iso2,
        "country_name":     snap.get("country_name", iso2),
        "date":             TODAY,
        "grdf_version":     "9.0",
        "generated_at":     datetime.now(timezone.utc).isoformat(),
        "n_candidates":     len(candidates),
        "candidates":       sorted(candidates, key=lambda x: -x["rank_score"]),
        "decision_confidence": dc_score,
        "ews_context":      float((_v9_load(f"v7_warning_score_{iso2}.json")).get("early_warning_score", 40)),
    }


# ── Phase 2: Autonomous Priority Score ───────────────────────────────────

def _aps(impact: float, urgency: float, feas: float, conf: float) -> float:
    """
    APS = impact*0.35 + urgency*0.25 + feasibility*0.20 + confidence*0.20
    All 0-100 inputs, output 0-100.
    """
    return max(0, min(100, round(impact*0.35 + urgency*0.25 + feas*0.20 + conf*0.20)))


def _build_v9_priority_score(iso2: str, snap: dict, cands: dict) -> dict:
    """Phase 2: compute APS for each candidate action."""
    warn_d  = _v9_load(f"v7_warning_score_{iso2}.json")
    ews     = float(warn_d.get("early_warning_score", 40))
    dc      = float(cands.get("decision_confidence", 60))

    scored = []
    for act in cands.get("candidates", []):
        impact  = float(act.get("des", 50))
        urgency = ews                              # EWS drives urgency
        feas    = float(act.get("des", 50))        # DES proxies feasibility
        # Speed bonus: faster actions get feasibility boost
        speed   = act.get("speed_days", 180)
        feas_adj= min(100, feas + max(0, (180 - speed) / 18))  # +1 per 18d faster
        aps     = _aps(impact, urgency, feas_adj, dc)
        scored.append({
            "id":           act["id"],
            "label":        act["label"],
            "domain":       act["domain"],
            "aps":          aps,
            "aps_grade":    _v9_aps_grade(aps),
            "impact":       round(impact),
            "urgency":      round(urgency),
            "feasibility":  round(feas_adj),
            "confidence":   round(dc),
            "speed_days":   speed,
        })
    scored.sort(key=lambda x: -x["aps"])

    return {
        "country":          iso2,
        "country_name":     snap.get("country_name", iso2),
        "date":             TODAY,
        "grdf_version":     "9.0",
        "generated_at":     datetime.now(timezone.utc).isoformat(),
        "top_action":       scored[0]["label"] if scored else "none",
        "top_aps":          scored[0]["aps"]   if scored else 0,
        "avg_aps":          round(sum(s["aps"] for s in scored)/max(1,len(scored)),1),
        "scored_actions":   scored,
    }


# ── Phase 3: Resource Allocation Engine ──────────────────────────────────

def _rae(priority: float, resource_avail: float, impl_speed: float) -> float:
    """
    RAE = priority*0.50 + resource_availability*0.30 + implementation_speed*0.20
    """
    return max(0, min(100, round(priority*0.50 + resource_avail*0.30 + impl_speed*0.20)))


def _build_v9_resource_allocation(iso2: str, snap: dict, priority: dict) -> dict:
    """
    Phase 3: Allocate resources across top actions.
    resource_availability = proxy from resilience (V4 stress test).
    """
    stress_d = _v9_load("v4_stress_tests.json")
    st_rec   = next((r for r in stress_d.get("stress_tests",[]) if r.get("country")==iso2), {})
    resilience = float(st_rec.get("resilience", 50))
    resource_avail = resilience           # resilient countries have more available resources

    allocations = []
    scored = priority.get("scored_actions", [])
    total_aps = max(1, sum(s["aps"] for s in scored[:5]))

    for act in scored[:5]:
        speed_days  = act.get("speed_days", 180)
        # Normalised implementation speed 0-100 (7d=100, 730d=0)
        impl_speed  = max(0, min(100, round((730 - speed_days) / 7.23)))
        rae_score   = _rae(act["aps"], resource_avail, impl_speed)
        # Budget share: proportional to APS weight in top-5
        budget_pct  = round(act["aps"] / total_aps * 100, 1)

        allocations.append({
            "id":               act["id"],
            "label":            act["label"],
            "rae_score":        rae_score,
            "budget_pct":       budget_pct,
            "resource_types":   {
                "budget":         round(budget_pct),
                "time":           speed_days,
                "personnel":      round(rae_score * 0.5),
                "infrastructure": round(rae_score * 0.3),
                "logistics":      round(rae_score * 0.2),
            },
        })

    return {
        "country":          iso2,
        "country_name":     snap.get("country_name", iso2),
        "date":             TODAY,
        "grdf_version":     "9.0",
        "generated_at":     datetime.now(timezone.utc).isoformat(),
        "resource_availability": round(resource_avail),
        "top_allocation":   allocations[0]["label"] if allocations else "none",
        "allocations":      allocations,
        "total_budget_tracked": sum(a["budget_pct"] for a in allocations),
    }


# ── Phase 4: Multi-Risk Optimization ─────────────────────────────────────

def _build_v9_multi_risk_plan(iso2: str, snap: dict, priority: dict) -> dict:
    """
    Phase 4: Generate an optimized cross-domain action plan.
    Ensures at least one action per active risk domain.
    """
    dom_s = _get_domain_scores(iso2, snap)
    active_domains = sorted(
        [(d, v["score"]) for d, v in dom_s.items() if v["score"] >= 45],
        key=lambda x: -x[1]
    )

    scored_acts = priority.get("scored_actions", [])
    # Assign top action per domain
    domain_coverage: dict = {}
    global_actions  = []

    for act in scored_acts:
        dom = act["domain"]
        if dom not in domain_coverage:
            domain_coverage[dom] = act
            global_actions.append({
                "priority":    len(global_actions)+1,
                "domain":      dom,
                "action_id":   act["id"],
                "action":      act["label"],
                "aps":         act["aps"],
            })

    # Fill uncovered active domains with generic action
    for dom, score in active_domains:
        if dom not in domain_coverage:
            global_actions.append({
                "priority":   len(global_actions)+1,
                "domain":     dom,
                "action_id":  "ACT-GEN",
                "action":     f"Monitor and assess {dom} risk",
                "aps":        round(score * 0.5),
            })

    # Optimization score: fraction of active domains covered
    n_covered = len(domain_coverage)
    n_active  = max(1, len(active_domains))
    opt_score = round(n_covered / n_active * 100)

    return {
        "country":          iso2,
        "country_name":     snap.get("country_name", iso2),
        "date":             TODAY,
        "grdf_version":     "9.0",
        "generated_at":     datetime.now(timezone.utc).isoformat(),
        "active_domains_n": n_active,
        "covered_domains_n":n_covered,
        "optimization_score": opt_score,
        "multi_risk_plan":  global_actions[:7],
    }


# ── Phase 5: Autonomous Escalation Logic ─────────────────────────────────

def _esc_index(risk_level: float, velocity: float, uncertainty: float) -> float:
    """
    Escalation Index = risk_level*0.40 + velocity*0.30 + uncertainty*0.30
    All 0-100, output 0-100.
    """
    return max(0, min(100, round(risk_level*0.40 + velocity*0.30 + uncertainty*0.30)))


def _build_v9_escalation(iso2: str, snap: dict) -> dict:
    """
    Phase 5: Autonomous escalation logic.
    risk_level  = risk_score / 100 × 100
    velocity    = |delta| * 5 (normalised)
    uncertainty = (100 - decision_confidence)
    """
    risk_level  = int(snap.get("risk_score", 50) or 50)
    delta       = abs(float(snap.get("delta", 0) or 0))
    velocity    = min(100, round(delta * 5))

    dc_d        = _v9_load(f"v8_decision_confidence_{iso2}.json")
    dc          = float(dc_d.get("decision_confidence", 60))
    uncertainty = max(0, round(100 - dc))

    esc_idx   = _esc_index(risk_level, velocity, uncertainty)
    esc_level = _v9_esc_level(esc_idx)

    # Auto-trigger recommended actions based on escalation level
    esc_triggers: list = []
    if esc_idx >= 70:
        esc_triggers.append("immediate_response_required")
    if velocity >= 30:
        esc_triggers.append("velocity_alert")
    if uncertainty >= 50:
        esc_triggers.append("high_uncertainty_flag")

    return {
        "country":          iso2,
        "country_name":     snap.get("country_name", iso2),
        "date":             TODAY,
        "grdf_version":     "9.0",
        "generated_at":     datetime.now(timezone.utc).isoformat(),
        "escalation_index": esc_idx,
        "escalation_level": esc_level,
        "risk_level":       risk_level,
        "velocity":         velocity,
        "uncertainty":      uncertainty,
        "auto_triggers":    esc_triggers,
        "n_triggers":       len(esc_triggers),
    }


# ── Phase 6: Dynamic Playbook Generator ──────────────────────────────────

def _build_v9_dynamic_playbook(iso2: str, snap: dict, priority: dict,
                                esc: dict) -> dict:
    """
    Phase 6: Generate adaptive playbook for 24h / 7d / 30d / 90d / 1yr.
    Buckets actions by speed_days + escalation level context.
    """
    esc_lvl   = esc.get("escalation_level","GREEN")
    esc_ord   = {"GREEN":0,"YELLOW":1,"ORANGE":2,"RED":3,"BLACK":4}
    esc_boost = esc_ord.get(esc_lvl, 0)    # higher escalation → earlier buckets

    def _bucket(speed_days: int, boost: int) -> str:
        effective = max(0, speed_days - boost * 15)
        if effective <= 1:   return "24h"
        if effective <= 7:   return "7d"
        if effective <= 30:  return "30d"
        if effective <= 90:  return "90d"
        return "1yr"

    playbook: dict[str, list] = {b: [] for b in _V9_PLAYBOOK_BUCKETS}
    for act in priority.get("scored_actions", []):
        bucket = _bucket(act.get("speed_days", 180), esc_boost)
        playbook[bucket].append({
            "id":     act["id"],
            "label":  act["label"],
            "aps":    act["aps"],
            "domain": act["domain"],
        })

    # Priority bucket = first non-empty bucket
    priority_bucket = next((b for b in _V9_PLAYBOOK_BUCKETS if playbook[b]), "1yr")

    return {
        "country":          iso2,
        "country_name":     snap.get("country_name", iso2),
        "date":             TODAY,
        "grdf_version":     "9.0",
        "generated_at":     datetime.now(timezone.utc).isoformat(),
        "escalation_level": esc_lvl,
        "playbook":         playbook,
        "priority_bucket":  priority_bucket,
        "n_actions_total":  sum(len(v) for v in playbook.values()),
    }


# ── Phase 7: Autonomous Scenario Switching ───────────────────────────────

def _build_v9_active_scenario(iso2: str, snap: dict) -> dict:
    """
    Phase 7: Determine the active scenario and detect any switch triggers.
    Reads V5 scenarios + V7 probabilities to find whether the current
    situation requires switching from baseline.
    """
    sc_d    = _v9_load(f"v5_scenarios_{iso2}.json")
    prob_d  = _v9_load(f"v7_probability_{iso2}.json")
    tte_d   = _v9_load(f"v7_tte_{iso2}.json")
    trans_d = _v9_load(f"v5_transitions_{iso2}.json")

    current = sc_d.get("most_probable","baseline")
    p_mat   = float(prob_d.get("p_materialization", 30))
    tte_cat = tte_d.get("time_to_event","1_year")

    # Switch trigger evaluation
    triggers_fired: list = []

    # Trigger 1: materialization probability changed significantly
    if p_mat >= 65:
        triggers_fired.append({"trigger":"probability_change",
                               "value": p_mat, "threshold":65})

    # Trigger 2: TTE became urgent
    if tte_cat in ("immediate","30_days","90_days"):
        triggers_fired.append({"trigger":"tte_change",
                               "tte_category": tte_cat})

    # Trigger 3: New risk from signals
    sig_d = _v9_load(f"v5_signals_{iso2}.json")
    if sig_d.get("signal_grade","noise") in ("strong","critical"):
        triggers_fired.append({"trigger":"new_risk",
                               "signal_grade": sig_d.get("signal_grade")})

    # Trigger 4: cascade effect
    casc_d = _v9_load(f"v2_cascades_{iso2}.json")
    if float(casc_d.get("max_cascade_score",0) or 0) >= 70:
        triggers_fired.append({"trigger":"cascade_effect",
                               "cascade_score": round(casc_d.get("max_cascade_score",0))})

    # Determine recommended scenario (switch if triggered)
    recommended = current
    if triggers_fired:
        if p_mat >= 80 or tte_cat in ("immediate","30_days"):
            recommended = "worst"
        elif p_mat >= 65 or tte_cat == "90_days":
            recommended = "stress"
        elif any(t["trigger"]=="probability_change" and t["value"]<40 for t in triggers_fired):
            recommended = "best_case"

    return {
        "country":          iso2,
        "country_name":     snap.get("country_name", iso2),
        "date":             TODAY,
        "grdf_version":     "9.0",
        "generated_at":     datetime.now(timezone.utc).isoformat(),
        "current_scenario": current,
        "recommended_scenario": recommended,
        "scenario_switch":  recommended != current,
        "p_materialization":p_mat,
        "tte_category":     tte_cat,
        "triggers_fired":   triggers_fired,
        "n_triggers":       len(triggers_fired),
    }


# ── Phase 8: Strategic Coordination Score ────────────────────────────────

def _scs(alignment: float, timing: float, efficiency: float) -> float:
    """
    SCS = alignment*0.40 + timing*0.30 + efficiency*0.30
    """
    return max(0, min(100, round(alignment*0.40 + timing*0.30 + efficiency*0.30)))


def _scs_grade(score: float) -> str:
    if score >= 75: return "strong"
    if score >= 50: return "moderate"
    return "weak"


def _build_v9_coordination(iso2: str, snap: dict, priority: dict,
                            esc: dict, active_sc: dict) -> dict:
    """
    Phase 8: SCS = alignment*0.40 + timing*0.30 + efficiency*0.30
    alignment  = % of active domains covered by top-5 actions
    timing     = inverse of escalation index (faster decisions = better timing)
    efficiency = average APS of top-5 actions
    """
    scored      = priority.get("scored_actions", [])[:5]
    esc_idx     = float(esc.get("escalation_index", 50))
    scenario_sw = active_sc.get("scenario_switch", False)

    # Alignment: domain coverage
    dom_s        = _get_domain_scores(iso2, snap)
    active_doms  = {d for d, v in dom_s.items() if v["score"] >= 45}
    covered_doms = {a["domain"] for a in scored}
    alignment    = round(len(covered_doms & active_doms) / max(1, len(active_doms)) * 100)

    # Timing: low escalation = more time to act = better timing
    timing       = max(0, round(100 - esc_idx * 0.6))

    # Efficiency: avg APS
    efficiency   = round(sum(a["aps"] for a in scored) / max(1, len(scored)))

    # Scenario switch penalty
    if scenario_sw:
        alignment  = max(0, alignment - 10)  # realignment needed

    scs_score = _scs(alignment, timing, efficiency)

    return {
        "country":              iso2,
        "country_name":         snap.get("country_name", iso2),
        "date":                 TODAY,
        "grdf_version":         "9.0",
        "generated_at":         datetime.now(timezone.utc).isoformat(),
        "scs":                  scs_score,
        "scs_grade":            _scs_grade(scs_score),
        "alignment":            alignment,
        "timing":               timing,
        "efficiency":           efficiency,
        "scenario_switch_active": scenario_sw,
    }


# ── Phase 9: Autonomous Confidence ────────────────────────────────────────

def _ac(fc_conf: float, model_agreement: float, data_quality: float) -> float:
    """
    AC = forecast_confidence*0.40 + model_agreement*0.30 + data_quality*0.30
    """
    return max(0, min(100, round(fc_conf*0.40 + model_agreement*0.30 + data_quality*0.30)))


def _build_v9_autonomous_confidence(iso2: str, snap: dict) -> dict:
    """
    Phase 9: Autonomous Confidence (AC) for V9 decisions.
    Extends V8 DC with model agreement from MC simulations.
    """
    dc_d     = _v9_load(f"v8_decision_confidence_{iso2}.json")
    mc_d     = _v9_load(f"v6_montecarlo_{iso2}.json")
    fc_d     = _v9_load(f"v3_forecast_{iso2}.json")

    fc_conf_raw = float((fc_d.get("horizons") or {}).get("30d", {}).get("confidence", 0.65) or 0.65)
    fc_conf     = round(fc_conf_raw * 100)

    # Model agreement: MC p50 vs forecast closeness (V8 uses same logic)
    mc_p50   = float((mc_d.get("horizons") or {}).get("5yr", {}).get("p50", 50) or 50)
    fc_365   = float((fc_d.get("horizons") or {}).get("365d", {}).get("score", 50) or 50)
    agreement_raw = max(0.0, 1.0 - abs(mc_p50 - fc_365) / 50.0)
    model_agreement = round(agreement_raw * 100)

    # Data quality: count available V1-V8 artefacts
    artefacts = [
        f"v3_forecast_{iso2}.json", f"v5_signals_{iso2}.json",
        f"v6_digital_twin_{iso2}.json", f"v7_warning_score_{iso2}.json",
        f"v8_response_rank_{iso2}.json",
    ]
    present      = sum(1 for a in artefacts if (GRDF_DIR / a).exists())
    data_quality = round(present / len(artefacts) * 100)

    ac_score = _ac(fc_conf, model_agreement, data_quality)

    return {
        "country":           iso2,
        "country_name":      snap.get("country_name", iso2),
        "date":              TODAY,
        "grdf_version":      "9.0",
        "generated_at":      datetime.now(timezone.utc).isoformat(),
        "autonomous_confidence": ac_score,
        "ac_grade":          ("high" if ac_score >= 70 else "moderate" if ac_score >= 40 else "low"),
        "components": {
            "forecast_confidence": fc_conf,
            "model_agreement":     model_agreement,
            "data_quality":        data_quality,
        },
    }


# ── Phase 10: Global Autonomous Dashboard ────────────────────────────────

def _save_v9_dashboard(snapshots: list,
                        all_priority: list, all_esc: list, all_rac: list,
                        all_multi: list, all_pb: list, all_sc: list,
                        all_coord: list, all_ac: list) -> None:
    """Phase 10: 10-widget Global Autonomous Dashboard."""
    now_ts = datetime.now(timezone.utc).isoformat()
    esc_ord = {"GREEN":0,"YELLOW":1,"ORANGE":2,"RED":3,"BLACK":4}

    # W1: Global Priorities — top APS per country
    global_priorities = sorted(
        [{"country":p["country"],"top_action":p["top_action"],"top_aps":p["top_aps"],"aps_grade":(_v9_aps_grade(p["top_aps"]))}
         for p in all_priority if p.get("top_aps")],
        key=lambda x: -x["top_aps"])[:10]

    # W2: Active Risks — highest risk + highest esc
    active_risks = sorted(
        [{"country":e["country"],"risk_level":e["risk_level"],"esc_idx":e["escalation_index"],"esc_level":e["escalation_level"]}
         for e in all_esc],
        key=lambda x: (-esc_ord.get(x["esc_level"],0), -x["esc_idx"]))[:10]

    # W3: Escalation Monitor — RED/BLACK countries
    esc_monitor = [e for e in all_esc if esc_ord.get(e["escalation_level"],0) >= 3]
    esc_monitor.sort(key=lambda x: -x["escalation_index"])

    # W4: Resource Allocation — top allocation per country
    resource_allocation = sorted(
        [{"country":r["country"],"top_allocation":r["top_allocation"],
          "resource_availability":r["resource_availability"]}
         for r in all_rac],
        key=lambda x: -x["resource_availability"])[:10]

    # W5: Strategic Coordination — SCS distribution
    coord_summary = sorted(
        [{"country":c["country"],"scs":c["scs"],"scs_grade":c["scs_grade"],"alignment":c["alignment"]}
         for c in all_coord],
        key=lambda x: -x["scs"])[:10]

    # W6: Dynamic Playbooks — how many have 24h priority actions
    dynamic_playbooks = sorted(
        [{"country":p["country"],"priority_bucket":p["priority_bucket"],
          "n_actions":p["n_actions_total"],"esc_level":p["escalation_level"]}
         for p in all_pb],
        key=lambda x: esc_ord.get(x["esc_level"],0), reverse=True)[:10]

    # W7: Scenario Switches — countries with active switch
    scenario_switches = [
        {"country":s["country"],"from":s["current_scenario"],"to":s["recommended_scenario"],
         "p_mat":s["p_materialization"],"tte":s["tte_category"]}
        for s in all_sc if s.get("scenario_switch")
    ]

    # W8: Autonomous Confidence
    ac_ranking = sorted(
        [{"country":a["country"],"ac":a["autonomous_confidence"],"grade":a["ac_grade"]}
         for a in all_ac],
        key=lambda x: -x["ac"])[:10]

    # W9: Global Action Atlas
    global_action_atlas = {p["country"]: {
        "top_action": p["top_action"],
        "top_aps":    p["top_aps"],
        "esc_level":  next((e["escalation_level"] for e in all_esc if e.get("country")==p["country"]), "GREEN"),
    } for p in all_priority}

    # W10: Global Mission Status
    avg_aps     = round(sum(p["top_aps"] for p in all_priority)/max(1,len(all_priority)),1)
    avg_scs     = round(sum(c["scs"]     for c in all_coord)   /max(1,len(all_coord)),1)
    avg_ac      = round(sum(a["autonomous_confidence"] for a in all_ac)/max(1,len(all_ac)),1)
    black_n     = sum(1 for e in all_esc if e["escalation_level"]=="BLACK")
    red_n       = sum(1 for e in all_esc if e["escalation_level"]=="RED")
    switches_n  = len(scenario_switches)
    mission_status = {
        "avg_aps":           avg_aps,
        "avg_scs":           avg_scs,
        "avg_autonomous_confidence": avg_ac,
        "critical_countries_n":   black_n + red_n,
        "scenario_switches_n":    switches_n,
        "countries_with_24h_action": sum(1 for p in all_pb if p["priority_bucket"]=="24h"),
    }

    with open(GRDF_DIR / "v9_dashboard.json","w") as f:
        json.dump({
            "grdf_version":         "9.0",
            "date":                 TODAY,
            "generated_at":         now_ts,
            "global_priorities":    global_priorities,
            "active_risks":         active_risks,
            "escalation_monitor":   esc_monitor,
            "resource_allocation":  resource_allocation,
            "strategic_coordination": coord_summary,
            "dynamic_playbooks":    dynamic_playbooks,
            "scenario_switches":    scenario_switches,
            "autonomous_confidence":ac_ranking,
            "global_action_atlas":  global_action_atlas,
            "global_mission_status":mission_status,
        }, f, ensure_ascii=False, indent=2)
    print("[GRDF-V9] Phase 10: Global Autonomous Dashboard", file=sys.stderr)


# ── V9 Orchestrator ───────────────────────────────────────────────────────

def save_grdf_v9(snapshots: list) -> None:
    """
    GRDF V9 -- Autonomous Strategic Intelligence.
    Dependency: V1->V2->...->V8->V9
    Reads: v1..v8 outputs.  Writes: v9_* only.
    V1/V2/V3/V4/V5/V6/V7/V8 NEVER modified.
    """
    GRDF_DIR.mkdir(parents=True, exist_ok=True)

    all_priority: list = []
    all_esc:      list = []
    all_rac:      list = []
    all_multi:    list = []
    all_pb:       list = []
    all_sc:       list = []
    all_coord:    list = []
    all_ac:       list = []

    for snap in snapshots:
        iso2 = snap["country"]
        try:
            # Phase 1
            cands = _build_v9_action_candidates(iso2, snap)
            with open(GRDF_DIR / f"v9_action_candidates_{iso2}.json","w") as f:
                json.dump(cands, f, ensure_ascii=False, indent=2)

            # Phase 2
            prio = _build_v9_priority_score(iso2, snap, cands)
            prio["country"] = iso2
            with open(GRDF_DIR / f"v9_priority_score_{iso2}.json","w") as f:
                json.dump(prio, f, ensure_ascii=False, indent=2)
            all_priority.append(prio)

            # Phase 3
            rac = _build_v9_resource_allocation(iso2, snap, prio)
            rac["country"] = iso2
            with open(GRDF_DIR / f"v9_resource_allocation_{iso2}.json","w") as f:
                json.dump(rac, f, ensure_ascii=False, indent=2)
            all_rac.append(rac)

            # Phase 4
            multi = _build_v9_multi_risk_plan(iso2, snap, prio)
            with open(GRDF_DIR / f"v9_multi_risk_plan_{iso2}.json","w") as f:
                json.dump(multi, f, ensure_ascii=False, indent=2)
            all_multi.append(multi)

            # Phase 5
            esc = _build_v9_escalation(iso2, snap)
            esc["country"] = iso2
            with open(GRDF_DIR / f"v9_escalation_{iso2}.json","w") as f:
                json.dump(esc, f, ensure_ascii=False, indent=2)
            all_esc.append(esc)

            # Phase 6
            pb = _build_v9_dynamic_playbook(iso2, snap, prio, esc)
            pb["country"] = iso2
            with open(GRDF_DIR / f"v9_dynamic_playbook_{iso2}.json","w") as f:
                json.dump(pb, f, ensure_ascii=False, indent=2)
            all_pb.append(pb)

            # Phase 7
            active_sc = _build_v9_active_scenario(iso2, snap)
            with open(GRDF_DIR / f"v9_active_scenario_{iso2}.json","w") as f:
                json.dump(active_sc, f, ensure_ascii=False, indent=2)
            all_sc.append(active_sc)

            # Phase 8
            coord = _build_v9_coordination(iso2, snap, prio, esc, active_sc)
            with open(GRDF_DIR / f"v9_coordination_{iso2}.json","w") as f:
                json.dump(coord, f, ensure_ascii=False, indent=2)
            all_coord.append(coord)

            # Phase 9
            ac = _build_v9_autonomous_confidence(iso2, snap)
            with open(GRDF_DIR / f"v9_autonomous_confidence_{iso2}.json","w") as f:
                json.dump(ac, f, ensure_ascii=False, indent=2)
            all_ac.append(ac)

        except Exception as e:
            print(f"[GRDF-V9] {iso2}: FAILED -- {e}", file=sys.stderr)

    # Phase 10: Dashboard
    _save_v9_dashboard(
        snapshots, all_priority, all_esc, all_rac,
        all_multi, all_pb, all_sc, all_coord, all_ac
    )

    print(f"[GRDF-V9] All 10 phases complete. {len(all_priority)} countries processed.", file=sys.stderr)


# =========================================================================
# GLOBAL RISK DATA FABRIC V10 -- Sovereign Intelligence Platform
#
# Unifies V1-V9 into a single sovereign-grade intelligence operating system.
#
# Phase 1:  Mission Control Engine      -> v10_missions_{CC}.json
# Phase 2:  Strategic Knowledge Graph   -> v10_knowledge_graph.json
# Phase 3:  Intelligence Memory Layer   -> v10_memory.json
# Phase 4:  Sovereign Agent Framework   -> v10_agents.json
# Phase 5:  Global Alert Network        -> v10_alert_network.json
# Phase 6:  Strategic Coordination Hub  -> v10_coordination.json
# Phase 7:  Global Action Atlas         -> v10_action_atlas.json
# Phase 8:  Autonomous Operations Engine-> v10_operations.json
# Phase 9:  Sovereign Intelligence Dashboard -> v10_dashboard.json
# Phase 10: Sovereign Intelligence API  -> (worker routes)
#
# Reads: v1..v9 outputs (read-only).
# Writes: v10_* only.  V1-V9 NEVER modified.
# =========================================================================

# Agent domains (Phase 4)
_V10_AGENTS = [
    "climate","economic","geopolitical",
    "infrastructure","energy","cyber","social",
]

# Mission lifecycle states
_V10_MISSION_STATES = ["pending","active","monitoring","escalated","resolved"]

# Alert level order
_V10_ALERT_ORDER = {"GREEN":0,"YELLOW":1,"ORANGE":2,"RED":3,"BLACK":4}


def _v10_load(path_rel: str) -> dict:
    p = GRDF_DIR / path_rel
    if p.exists():
        try:
            return json.loads(p.read_text())
        except Exception:
            return {}
    return {}


# ── Phase 1: Mission Control Engine ──────────────────────────────────────

def _build_v10_missions(iso2: str, snap: dict) -> dict:
    """
    Phase 1: Generate strategic missions for a country from V7-V9 outputs.
    Each mission has: objective, priority, status, actions, owner_agent, lifecycle.
    """
    warn_d   = _v10_load(f"v7_warning_score_{iso2}.json")
    alert_d  = _v10_load(f"v7_alerts_{iso2}.json")
    prio_d   = _v10_load(f"v9_priority_score_{iso2}.json")
    esc_d    = _v10_load(f"v9_escalation_{iso2}.json")

    ews        = float(warn_d.get("early_warning_score", 40))
    alert_lvl  = alert_d.get("alert_level","GREEN")
    esc_level  = esc_d.get("escalation_level","GREEN")
    top_action = prio_d.get("top_action","assess and monitor")

    # Mission lifecycle state driven by escalation
    esc_ord = _V10_ALERT_ORDER.get(esc_level, 0)
    state   = (_V10_MISSION_STATES[min(4, max(0, esc_ord + 1))]
               if esc_ord >= 2 else "monitoring")

    # Generate 3-5 missions based on active risk domains
    dom_s    = _get_domain_scores(iso2, snap)
    top_doms = sorted(dom_s.items(), key=lambda x: -x[1].get("score",0))[:5]

    missions = []
    for i, (dom, dv) in enumerate(top_doms, 1):
        priority = "critical" if dv["score"] >= 75 else "high" if dv["score"] >= 55 else "standard"
        missions.append({
            "mission_id":    f"MSN-{iso2}-{i:02d}",
            "objective":     f"Mitigate {dom} risk in {snap.get('country_name',iso2)}",
            "domain":        dom,
            "priority":      priority,
            "status":        state if i == 1 else "monitoring",
            "domain_score":  dv["score"],
            "owner_agent":   dom,
            "top_action":    top_action if i == 1 else f"Monitor {dom} indicators",
            "lifecycle":     {
                "created":   TODAY,
                "updated":   TODAY,
                "state":     state if i == 1 else "monitoring",
                "ews":       round(ews),
                "alert":     alert_lvl,
            },
        })

    return {
        "country":      iso2,
        "country_name": snap.get("country_name", iso2),
        "date":         TODAY,
        "grdf_version": "10.0",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "n_missions":   len(missions),
        "active_n":     sum(1 for m in missions if m["status"] in ("active","escalated")),
        "missions":     missions,
        "overall_status": state,
    }


# ── Phase 2: Strategic Knowledge Graph ───────────────────────────────────

def _build_v10_knowledge_graph(snapshots: list) -> dict:
    """
    Phase 2: Global knowledge graph connecting risks, events, countries,
    infrastructure, policies, scenarios, and decisions.
    Node types: Country, Risk, Event, Infrastructure, Policy, Scenario, Decision
    Edge types: LINKED_TO, CAUSES, AFFECTS, MITIGATES, ENABLES, AMPLIFIES
    """
    nodes: list[dict] = []
    edges: list[dict] = []
    seen: set = set()

    def add(nid, ntype, label, **kw):
        if nid not in seen:
            seen.add(nid)
            nodes.append({"id":nid,"type":ntype,"label":label,**kw})

    for snap in snapshots:
        iso2 = snap["country"]
        score = int(snap.get("risk_score",50) or 50)
        add(f"CC:{iso2}","Country",snap.get("country_name",iso2),risk_score=score)

        # Risk nodes per domain
        dom_s = _get_domain_scores(iso2, snap)
        for d, dv in dom_s.items():
            rid = f"RISK:{iso2}:{d}"
            add(rid,"Risk",f"{iso2} {d} risk",score=dv["score"],domain=d)
            edges.append({"from":f"CC:{iso2}","to":rid,"type":"LINKED_TO","weight":dv["score"]/100})
            # High-score domains cause cascades
            if dv["score"] >= 65:
                edges.append({"from":rid,"to":f"CC:{iso2}","type":"AFFECTS","weight":dv["score"]/100})

        # Decision nodes from V8
        rank_d   = _v10_load(f"v8_response_rank_{iso2}.json")
        top10    = (rank_d.get("top10") or [])[:3]
        for act in top10:
            did = f"DEC:{iso2}:{act['id']}"
            add(did,"Decision",act.get("label","?")[:40],domain=act.get("domain","?"))
            edges.append({"from":did,"to":f"CC:{iso2}","type":"MITIGATES","weight":act.get("rank_score",50)/100})

        # Scenario nodes from V5
        sc_d = _v10_load(f"v5_scenarios_{iso2}.json")
        prob  = sc_d.get("most_probable","baseline")
        sid   = f"SCN:{iso2}:{prob}"
        add(sid,"Scenario",f"{iso2} {prob} scenario",probability=prob)
        edges.append({"from":f"CC:{iso2}","to":sid,"type":"LINKED_TO","weight":0.75})

        # Policy nodes from V8
        pol_d   = _v10_load(f"v8_policy_impacts_{iso2}.json")
        best_pol= pol_d.get("best_policy","energy_policy")
        pid     = f"POL:{iso2}:{best_pol}"
        add(pid,"Policy",f"{iso2} {best_pol}",gri_lift=pol_d.get("max_gri_lift",0))
        edges.append({"from":pid,"to":f"CC:{iso2}","type":"ENABLES","weight":0.70})

    # Cross-country edges from V6 links
    link_d = _v10_load("v6_country_links.json")
    for lnk in (link_d.get("matrix") or [])[:50]:
        a, b = lnk.get("from",""), lnk.get("to","")
        if a and b:
            edges.append({"from":f"CC:{a}","to":f"CC:{b}","type":"LINKED_TO",
                          "weight":lnk.get("strength",0.3)})

    return {
        "grdf_version":   "10.0",
        "date":           TODAY,
        "generated_at":   datetime.now(timezone.utc).isoformat(),
        "node_count":     len(nodes),
        "edge_count":     len(edges),
        "node_types":     ["Country","Risk","Event","Infrastructure","Policy","Scenario","Decision"],
        "edge_types":     ["LINKED_TO","CAUSES","AFFECTS","MITIGATES","ENABLES","AMPLIFIES"],
        "nodes":          nodes,
        "edges":          edges,
    }


# ── Phase 3: Intelligence Memory Layer ───────────────────────────────────

def _build_v10_memory(snapshots: list) -> dict:
    """
    Phase 3: Persistent intelligence memory — aggregates signals, forecasts,
    scenarios, decisions, and action results across V1-V9.
    """
    memory_records = []
    for snap in snapshots:
        iso2 = snap["country"]
        # Signals from V5
        sig   = _v10_load(f"v5_signals_{iso2}.json")
        # Forecast from V3
        fc    = _v10_load(f"v3_forecast_{iso2}.json")
        # Scenario from V5
        sc    = _v10_load(f"v5_scenarios_{iso2}.json")
        # Decision rank from V8
        rank  = _v10_load(f"v8_response_rank_{iso2}.json")
        # Materialization probability from V7
        prob  = _v10_load(f"v7_probability_{iso2}.json")

        memory_records.append({
            "country":        iso2,
            "country_name":   snap.get("country_name", iso2),
            "date":           TODAY,
            # Signals
            "signal_score":   sig.get("signal_score",0),
            "signal_grade":   sig.get("signal_grade","noise"),
            # Forecast
            "forecast_30d":   (fc.get("horizons") or {}).get("30d",{}).get("score"),
            "forecast_90d":   (fc.get("horizons") or {}).get("90d",{}).get("score"),
            # Scenario
            "active_scenario":sc.get("most_probable","baseline"),
            # Decision
            "top_decision":   rank.get("top_action","?"),
            # Probability
            "p_materialization": prob.get("p_materialization",0),
            # Current state
            "risk_score":     int(snap.get("risk_score",50) or 50),
            "alert_level":    snap.get("alert_level","NONE") or "NONE",
        })

    return {
        "grdf_version":   "10.0",
        "date":           TODAY,
        "generated_at":   datetime.now(timezone.utc).isoformat(),
        "total_records":  len(memory_records),
        "memory":         memory_records,
        "layer_coverage": {
            "V1_risk":          True,
            "V3_forecast":      True,
            "V5_scenarios":     True,
            "V7_warnings":      True,
            "V8_decisions":     True,
            "V9_autonomous":    True,
        },
    }


# ── Phase 4: Sovereign Agent Framework ───────────────────────────────────

def _build_v10_agents(snapshots: list) -> dict:
    """
    Phase 4: Multi-agent framework — one specialist agent per domain.
    Each agent monitors its domain across all 25 countries and
    generates domain-specific intelligence briefs.
    """
    agents: dict = {}
    for agent_domain in _V10_AGENTS:
        agent_countries = []
        for snap in snapshots:
            iso2  = snap["country"]
            dom_s = _get_domain_scores(iso2, snap)
            dv    = dom_s.get(agent_domain, {})
            score = dv.get("score", 50)
            trend = dv.get("trend","stable")
            if score >= 40:       # only include where domain is active
                agent_countries.append({
                    "country":     iso2,
                    "country_name":snap.get("country_name",iso2),
                    "domain_score":score,
                    "trend":       trend,
                    "velocity":    dv.get("velocity",0),
                    "alert":       snap.get("alert_level","NONE") or "NONE",
                })

        agent_countries.sort(key=lambda x: -x["domain_score"])
        avg_score = round(sum(a["domain_score"] for a in agent_countries)
                          / max(1,len(agent_countries)),1)

        agents[agent_domain] = {
            "agent_id":       f"AGT-{agent_domain.upper()[:6]}",
            "domain":         agent_domain,
            "monitoring_n":   len(agent_countries),
            "avg_domain_score": avg_score,
            "top_country":    agent_countries[0]["country"] if agent_countries else "N/A",
            "top_score":      agent_countries[0]["domain_score"] if agent_countries else 0,
            "status":         ("alert" if avg_score >= 65 else
                               "elevated" if avg_score >= 45 else "normal"),
            "countries":      agent_countries[:10],
        }

    return {
        "grdf_version":   "10.0",
        "date":           TODAY,
        "generated_at":   datetime.now(timezone.utc).isoformat(),
        "total_agents":   len(agents),
        "agents":         agents,
        "agent_domains":  _V10_AGENTS,
    }


# ── Phase 5: Global Alert Network ────────────────────────────────────────

def _build_v10_alert_network(snapshots: list) -> dict:
    """
    Phase 5: Unified V10 global alert network — merges V7 alerts,
    V9 escalation, and V8 materialization probability into a
    single 5-level sovereign alert layer.
    """
    alert_map: dict = {}
    for snap in snapshots:
        iso2    = snap["country"]
        v7_al   = _v10_load(f"v7_alerts_{iso2}.json")
        v9_esc  = _v10_load(f"v9_escalation_{iso2}.json")
        v7_prob = _v10_load(f"v7_probability_{iso2}.json")

        v7_level = v7_al.get("alert_level","GREEN")
        v9_level = v9_esc.get("escalation_level","GREEN")
        p_mat    = float(v7_prob.get("p_materialization",30))

        # Sovereign alert = max of V7 + V9, boosted by high p_mat
        sov_ord  = max(_V10_ALERT_ORDER.get(v7_level,0),
                       _V10_ALERT_ORDER.get(v9_level,0))
        if p_mat >= 80: sov_ord = min(4, sov_ord + 1)
        sov_level= ["GREEN","YELLOW","ORANGE","RED","BLACK"][sov_ord]

        alert_map[iso2] = {
            "country":         iso2,
            "country_name":    snap.get("country_name",iso2),
            "sovereign_alert": sov_level,
            "v7_alert":        v7_level,
            "v9_escalation":   v9_level,
            "p_materialization":round(p_mat),
            "risk_score":      int(snap.get("risk_score",50) or 50),
        }

    # Count per level
    counts: dict = {l:0 for l in ["GREEN","YELLOW","ORANGE","RED","BLACK"]}
    for v in alert_map.values():
        counts[v["sovereign_alert"]] += 1

    by_severity = sorted(alert_map.values(),
                         key=lambda x: -_V10_ALERT_ORDER.get(x["sovereign_alert"],0))

    return {
        "grdf_version":    "10.0",
        "date":            TODAY,
        "generated_at":    datetime.now(timezone.utc).isoformat(),
        "level_counts":    counts,
        "critical_n":      counts["BLACK"] + counts["RED"],
        "top_alerts":      by_severity[:10],
        "alert_map":       alert_map,
    }


# ── Phase 6: Strategic Coordination Hub ──────────────────────────────────

def _build_v10_coordination(snapshots: list) -> dict:
    """
    Phase 6: Cross-country strategic coordination.
    Groups countries by region, identifies shared threats,
    and proposes synchronized response actions.
    """
    from collections import defaultdict as _dd

    region_groups: dict = _dd(list)
    for snap in snapshots:
        iso2 = snap["country"]
        reg  = _CC_REGION.get(iso2, 0)
        region_groups[reg].append(iso2)

    coordination_blocks = []
    for reg_id, ccs in region_groups.items():
        if len(ccs) < 2:
            continue
        # Average risk in region
        scores = [int(s.get("risk_score",50) or 50)
                  for s in snapshots if s["country"] in ccs]
        avg_sc  = round(sum(scores)/max(1,len(scores)))
        # Shared dominant domain
        dom_freq: dict = {}
        for s in snapshots:
            if s["country"] in ccs:
                dom = (s.get("dominant_domain","geopolitical") or "geopolitical").lower()
                dom = _ENGINE_TO_GRDF.get(dom, dom)
                dom_freq[dom] = dom_freq.get(dom,0)+1
        shared_dom = max(dom_freq.items(), key=lambda x:x[1])[0] if dom_freq else "geopolitical"

        # Load V9 coordination score for region countries
        scs_vals = []
        for iso2 in ccs:
            cd = _v10_load(f"v9_coordination_{iso2}.json")
            if cd.get("scs"): scs_vals.append(float(cd["scs"]))
        avg_scs = round(sum(scs_vals)/max(1,len(scs_vals)),1)

        coordination_blocks.append({
            "region_id":        reg_id,
            "countries":        ccs,
            "avg_risk":         avg_sc,
            "shared_domain":    shared_dom,
            "avg_scs":          avg_scs,
            "coordination_grade": ("strong" if avg_scs >= 70 else
                                   "moderate" if avg_scs >= 45 else "weak"),
            "recommended_action": f"Regional {shared_dom} risk coordination",
        })

    coordination_blocks.sort(key=lambda x: -x["avg_risk"])

    return {
        "grdf_version":       "10.0",
        "date":               TODAY,
        "generated_at":       datetime.now(timezone.utc).isoformat(),
        "total_regions":      len(coordination_blocks),
        "coordination_blocks":coordination_blocks,
        "global_avg_scs":     round(sum(b["avg_scs"] for b in coordination_blocks)/
                                    max(1,len(coordination_blocks)),1),
    }


# ── Phase 7: Global Action Atlas ─────────────────────────────────────────

def _build_v10_action_atlas(snapshots: list) -> dict:
    """
    Phase 7: Comprehensive catalogue of all strategic actions across
    all countries — playbooks, mitigation, adaptation, resilience, emergency.
    """
    atlas_entries = []
    action_types = {
        "playbook":    "v9_dynamic_playbook",
        "mitigation":  "v8_mitigation",
        "resilience":  "v8_response_rank",
    }

    for snap in snapshots:
        iso2    = snap["country"]
        country_actions: list = []

        # V9 dynamic playbook
        pb      = _v10_load(f"v9_dynamic_playbook_{iso2}.json")
        for bucket, acts in (pb.get("playbook") or {}).items():
            for act in acts[:2]:
                country_actions.append({
                    "action_type": "playbook",
                    "bucket":      bucket,
                    "id":          act.get("id","?"),
                    "label":       act.get("label","?"),
                    "aps":         act.get("aps",0),
                })

        # V8 top mitigation
        mit     = _v10_load(f"v8_mitigation_{iso2}.json")
        for m in (mit.get("mitigations") or [])[:3]:
            country_actions.append({
                "action_type": "mitigation",
                "id":          m.get("id","?"),
                "label":       m.get("label","?"),
                "ms":          m.get("mitigation_score",0),
            })

        atlas_entries.append({
            "country":     iso2,
            "country_name":snap.get("country_name",iso2),
            "n_actions":   len(country_actions),
            "actions":     country_actions[:10],
            "priority_bucket": pb.get("priority_bucket","1yr"),
        })

    atlas_entries.sort(key=lambda x: x["priority_bucket"])

    return {
        "grdf_version":  "10.0",
        "date":          TODAY,
        "generated_at":  datetime.now(timezone.utc).isoformat(),
        "total_countries": len(atlas_entries),
        "total_actions": sum(e["n_actions"] for e in atlas_entries),
        "action_types":  ["playbook","mitigation","adaptation","resilience","emergency"],
        "atlas":         atlas_entries,
    }


# ── Phase 8: Autonomous Operations Engine ────────────────────────────────

def _build_v10_operations(snapshots: list, alert_net: dict) -> dict:
    """
    Phase 8: Autonomous operations — determines which playbooks are
    currently running, which scenarios are active, and what strategic
    shifts are under way.
    """
    now_ts      = datetime.now(timezone.utc).isoformat()
    operations  = []

    for snap in snapshots:
        iso2    = snap["country"]
        pb      = _v10_load(f"v9_dynamic_playbook_{iso2}.json")
        sc      = _v10_load(f"v9_active_scenario_{iso2}.json")
        esc     = _v10_load(f"v9_escalation_{iso2}.json")
        alert   = alert_net.get("alert_map",{}).get(iso2,{})

        playbook_status = "idle"
        bucket          = pb.get("priority_bucket","1yr")
        if bucket == "24h":   playbook_status = "executing"
        elif bucket == "7d":  playbook_status = "activated"
        elif bucket == "30d": playbook_status = "planned"

        operations.append({
            "country":          iso2,
            "country_name":     snap.get("country_name",iso2),
            "playbook_status":  playbook_status,
            "priority_bucket":  bucket,
            "scenario_active":  sc.get("current_scenario","baseline"),
            "scenario_switch":  sc.get("scenario_switch",False),
            "escalation_level": esc.get("escalation_level","GREEN"),
            "sovereign_alert":  alert.get("sovereign_alert","GREEN"),
            "auto_triggers_n":  esc.get("n_triggers",0),
        })

    executing = [op for op in operations if op["playbook_status"] == "executing"]
    activated = [op for op in operations if op["playbook_status"] == "activated"]
    switches  = [op for op in operations if op["scenario_switch"]]

    return {
        "grdf_version":      "10.0",
        "date":              TODAY,
        "generated_at":      now_ts,
        "executing_n":       len(executing),
        "activated_n":       len(activated),
        "scenario_switches_n": len(switches),
        "operations":        sorted(operations,
            key=lambda x: -_V10_ALERT_ORDER.get(x["sovereign_alert"],0)),
        "executing":         executing,
        "scenario_switches": switches,
    }


# ── Phase 9: Sovereign Intelligence Dashboard ─────────────────────────────

def _save_v10_dashboard(snapshots: list,
                         all_missions: list,
                         alert_net: dict,
                         agents: dict,
                         coord: dict,
                         atlas: dict,
                         ops: dict) -> None:
    """
    Phase 9: 10-layer Sovereign Intelligence Dashboard — unified view
    of all V1-V9 intelligence across all 25 countries.
    """
    now_ts = datetime.now(timezone.utc).isoformat()
    alert_ord = _V10_ALERT_ORDER

    # Layer 1: Global Risk Map
    risk_map = sorted(
        [{"country":s["country"],"country_name":s.get("country_name",s["country"]),
          "risk_score":int(s.get("risk_score",50) or 50),
          "alert_level":s.get("alert_level","NONE") or "NONE"}
         for s in snapshots],
        key=lambda x: -x["risk_score"])

    # Layer 2: Alert Layer
    alert_layer = alert_net.get("top_alerts",[])[:10]

    # Layer 3: Forecast Layer (30d change)
    forecast_layer = []
    for s in snapshots:
        iso2 = s["country"]
        fc   = _v10_load(f"v3_forecast_{iso2}.json")
        s30  = (fc.get("horizons") or {}).get("30d",{}).get("score", int(s.get("risk_score",50) or 50))
        delta= s30 - int(s.get("risk_score",50) or 50)
        forecast_layer.append({"country":iso2,"delta_30d":delta,"forecast_30d":s30})
    forecast_layer.sort(key=lambda x: -abs(x["delta_30d"]))

    # Layer 4: Scenario Layer
    scenario_layer = []
    for s in snapshots:
        iso2 = s["country"]
        sc   = _v10_load(f"v9_active_scenario_{iso2}.json")
        scenario_layer.append({
            "country":  iso2,
            "scenario": sc.get("current_scenario","baseline"),
            "switch":   sc.get("scenario_switch",False),
        })

    # Layer 5: Digital Twin summary
    twin_layer = []
    for s in snapshots:
        iso2 = s["country"]
        dt   = _v10_load(f"v6_digital_twin_{iso2}.json")
        twin_layer.append({
            "country":     iso2,
            "state_score": (dt.get("state") or {}).get("state_score",0),
            "bif_grade":   dt.get("bifurcation_grade","stable"),
        })
    twin_layer.sort(key=lambda x: -x["state_score"])

    # Layer 6: Decision Layer
    decision_layer = []
    for s in snapshots:
        iso2 = s["country"]
        rank = _v10_load(f"v8_response_rank_{iso2}.json")
        decision_layer.append({
            "country":    iso2,
            "top_action": rank.get("top_action","?"),
            "rank_score": (rank.get("top10") or [{}])[0].get("rank_score",0),
        })
    decision_layer.sort(key=lambda x: -x["rank_score"])

    # Layer 7: Autonomous Layer (V9 APS)
    autonomous_layer = []
    for s in snapshots:
        iso2 = s["country"]
        prio = _v10_load(f"v9_priority_score_{iso2}.json")
        autonomous_layer.append({
            "country":  iso2,
            "top_aps":  prio.get("top_aps",0),
            "action":   prio.get("top_action","?"),
        })
    autonomous_layer.sort(key=lambda x: -x["top_aps"])

    # Layer 8: Resource Layer
    resource_layer = []
    for s in snapshots:
        iso2 = s["country"]
        rac  = _v10_load(f"v9_resource_allocation_{iso2}.json")
        resource_layer.append({
            "country": iso2,
            "resource_availability": rac.get("resource_availability",50),
            "top_allocation": rac.get("top_allocation","?"),
        })
    resource_layer.sort(key=lambda x: -x["resource_availability"])

    # Layer 9: Mission Layer
    mission_layer = sorted(
        [{"country":m["country"],"n_missions":m["n_missions"],
          "active_n":m["active_n"],"status":m["overall_status"]}
         for m in all_missions],
        key=lambda x: -x["active_n"])[:10]

    # Layer 10: Coordination Layer
    coordination_layer = coord.get("coordination_blocks",[])[:5]

    # Summary
    summary = {
        "total_countries":   len(snapshots),
        "black_alerts":      alert_net.get("level_counts",{}).get("BLACK",0),
        "red_alerts":        alert_net.get("level_counts",{}).get("RED",0),
        "orange_alerts":     alert_net.get("level_counts",{}).get("ORANGE",0),
        "executing_playbooks": ops.get("executing_n",0),
        "scenario_switches": ops.get("scenario_switches_n",0),
        "global_avg_scs":    coord.get("global_avg_scs",0),
        "sovereign_status":  ("critical"  if alert_net.get("level_counts",{}).get("BLACK",0)>=2 else
                              "elevated"  if alert_net.get("level_counts",{}).get("RED",0)>=3 else
                              "monitoring"),
    }

    with open(GRDF_DIR / "v10_dashboard.json","w") as f:
        json.dump({
            "grdf_version":      "10.0",
            "date":              TODAY,
            "generated_at":      now_ts,
            "summary":           summary,
            "global_risk_map":   risk_map,
            "alert_layer":       alert_layer,
            "forecast_layer":    forecast_layer[:10],
            "scenario_layer":    scenario_layer,
            "digital_twin_layer":twin_layer[:10],
            "decision_layer":    decision_layer[:10],
            "autonomous_layer":  autonomous_layer[:10],
            "resource_layer":    resource_layer[:10],
            "mission_layer":     mission_layer,
            "coordination_layer":coordination_layer,
        }, f, ensure_ascii=False, indent=2)
    print("[GRDF-V10] Phase 9: Sovereign Intelligence Dashboard", file=sys.stderr)


# ── V10 Orchestrator ──────────────────────────────────────────────────────

def save_grdf_v10(snapshots: list) -> None:
    """
    GRDF V10 -- Sovereign Intelligence Platform.
    Dependency: V1->V2->...->V9->V10
    Reads: v1..v9 outputs.  Writes: v10_* only.
    V1/V2/V3/V4/V5/V6/V7/V8/V9 NEVER modified.
    """
    GRDF_DIR.mkdir(parents=True, exist_ok=True)
    now_ts = datetime.now(timezone.utc).isoformat()

    # Phase 1: Mission Control
    all_missions: list = []
    for snap in snapshots:
        iso2 = snap["country"]
        try:
            m = _build_v10_missions(iso2, snap)
            with open(GRDF_DIR / f"v10_missions_{iso2}.json","w") as f:
                json.dump(m, f, ensure_ascii=False, indent=2)
            all_missions.append(m)
        except Exception as e:
            print(f"[GRDF-V10] missions {iso2}: {e}", file=sys.stderr)
    print(f"[GRDF-V10] Phase 1: {len(all_missions)} mission records", file=sys.stderr)

    # Phase 2: Knowledge Graph
    try:
        kg = _build_v10_knowledge_graph(snapshots)
        with open(GRDF_DIR / "v10_knowledge_graph.json","w") as f:
            json.dump(kg, f, ensure_ascii=False, indent=2)
        print(f"[GRDF-V10] Phase 2: knowledge graph {kg['node_count']} nodes {kg['edge_count']} edges", file=sys.stderr)
    except Exception as e:
        print(f"[GRDF-V10] knowledge graph: {e}", file=sys.stderr)
        kg = {}

    # Phase 3: Memory
    try:
        mem = _build_v10_memory(snapshots)
        with open(GRDF_DIR / "v10_memory.json","w") as f:
            json.dump(mem, f, ensure_ascii=False, indent=2)
        print(f"[GRDF-V10] Phase 3: memory {mem['total_records']} records", file=sys.stderr)
    except Exception as e:
        print(f"[GRDF-V10] memory: {e}", file=sys.stderr)

    # Phase 4: Agents
    try:
        agents = _build_v10_agents(snapshots)
        with open(GRDF_DIR / "v10_agents.json","w") as f:
            json.dump(agents, f, ensure_ascii=False, indent=2)
        print(f"[GRDF-V10] Phase 4: {agents['total_agents']} agents", file=sys.stderr)
    except Exception as e:
        print(f"[GRDF-V10] agents: {e}", file=sys.stderr)
        agents = {}

    # Phase 5: Alert Network
    try:
        alert_net = _build_v10_alert_network(snapshots)
        with open(GRDF_DIR / "v10_alert_network.json","w") as f:
            json.dump(alert_net, f, ensure_ascii=False, indent=2)
        print(f"[GRDF-V10] Phase 5: alert network critical={alert_net.get('critical_n',0)}", file=sys.stderr)
    except Exception as e:
        print(f"[GRDF-V10] alert network: {e}", file=sys.stderr)
        alert_net = {"alert_map":{},"level_counts":{},"critical_n":0,"top_alerts":[]}

    # Phase 6: Coordination
    try:
        coord = _build_v10_coordination(snapshots)
        with open(GRDF_DIR / "v10_coordination.json","w") as f:
            json.dump(coord, f, ensure_ascii=False, indent=2)
        print(f"[GRDF-V10] Phase 6: {coord['total_regions']} regional blocks", file=sys.stderr)
    except Exception as e:
        print(f"[GRDF-V10] coordination: {e}", file=sys.stderr)
        coord = {"coordination_blocks":[],"global_avg_scs":0,"total_regions":0}

    # Phase 7: Action Atlas
    try:
        atlas = _build_v10_action_atlas(snapshots)
        with open(GRDF_DIR / "v10_action_atlas.json","w") as f:
            json.dump(atlas, f, ensure_ascii=False, indent=2)
        print(f"[GRDF-V10] Phase 7: action atlas {atlas['total_actions']} actions", file=sys.stderr)
    except Exception as e:
        print(f"[GRDF-V10] action atlas: {e}", file=sys.stderr)
        atlas = {}

    # Phase 8: Operations
    try:
        ops = _build_v10_operations(snapshots, alert_net)
        with open(GRDF_DIR / "v10_operations.json","w") as f:
            json.dump(ops, f, ensure_ascii=False, indent=2)
        print(f"[GRDF-V10] Phase 8: operations executing={ops['executing_n']}", file=sys.stderr)
    except Exception as e:
        print(f"[GRDF-V10] operations: {e}", file=sys.stderr)
        ops = {"executing_n":0,"activated_n":0,"scenario_switches_n":0,"operations":[],"executing":[],"scenario_switches":[]}

    # Phase 9: Dashboard
    try:
        _save_v10_dashboard(snapshots, all_missions, alert_net,
                            agents, coord, atlas, ops)
    except Exception as e:
        print(f"[GRDF-V10] dashboard: {e}", file=sys.stderr)

    print(f"[GRDF-V10] Sovereign Intelligence Platform OPERATIONAL. {len(snapshots)} countries.", file=sys.stderr)


