LIVE_OPS_DIR = DOCS_DIR / "live_operations"

# Live data source catalogue (Phase 1)
_LO_SOURCES = [
    {"id":"NASA_FIRMS", "domain":"climate",     "feed":"fire_alerts",       "interval_h":3},
    {"id":"GDACS",      "domain":"climate",     "feed":"disaster_alerts",   "interval_h":6},
    {"id":"USGS",       "domain":"climate",     "feed":"seismic_data",      "interval_h":1},
    {"id":"EMSC",       "domain":"climate",     "feed":"earthquake_events", "interval_h":1},
    {"id":"ACLED",      "domain":"geopolitical","feed":"conflict_events",   "interval_h":24},
    {"id":"GDELT",      "domain":"geopolitical","feed":"global_events",     "interval_h":1},
    {"id":"ReliefWeb",  "domain":"social",      "feed":"humanitarian",      "interval_h":24},
    {"id":"Copernicus", "domain":"climate",     "feed":"earth_observation", "interval_h":24},
]

# Event lifecycle stages (Phase 2)
_LO_EVENT_STAGES = ["detected","classified","forecasted","escalated","resolved"]

# Alert levels (Phase 5)
_LO_ALERT_LEVELS = ["GREEN","YELLOW","ORANGE","RED","BLACK"]
_LO_ALERT_ORD    = {l:i for i,l in enumerate(_LO_ALERT_LEVELS)}

# OHS weights (Phase 8)
_LO_OHS_WEIGHTS = {
    "forecast_quality": 0.25,
    "warning_quality":  0.25,
    "alert_quality":    0.20,
    "data_quality":     0.15,
    "platform_health":  0.15,
}

# Weekly review windows
_LO_FORECAST_WINDOWS = ["7d","30d","90d"]


def _lo_load(rel: str) -> dict:
    """Load from docs/grdf/"""
    p = GRDF_DIR / rel
    if p.exists():
        try: return json.loads(p.read_text())
        except Exception: return {}
    return {}

def _lo_load_hv(rel: str) -> dict:
    """Load from docs/historical_validation/"""
    p = DOCS_DIR / "historical_validation" / rel
    if p.exists():
        try: return json.loads(p.read_text())
        except Exception: return {}
    return {}

def _lo_load_prod(rel: str) -> dict:
    """Load from docs/production/"""
    p = DOCS_DIR / "production" / rel
    if p.exists():
        try: return json.loads(p.read_text())
        except Exception: return {}
    return {}


# ── Phase 1: Live Signal Registry ────────────────────────────────────────

def _build_lo_signal_registry(snapshots: list) -> dict:
    """
    Phase 1: Compute per-source signal metrics from current snapshot state.
    signals_per_day  = estimated from domain risk velocity
    signal_quality   = domain score coverage
    signal_latency   = source interval proxy
    """
    total_sig   = 0
    source_stats= []

    for src in _LO_SOURCES:
        domain    = src["domain"]
        interval  = src["interval_h"]

        # Signals/day: country signals in this domain / interval_h × 24
        dom_scores= [_get_domain_scores(s["country"],s).get(domain,{}).get("score",0) for s in snapshots]
        active    = sum(1 for sc in dom_scores if sc >= 40)
        sig_day   = round(active * (24 / max(1, interval)) * 0.1, 1)
        total_sig += sig_day

        # Quality: mean domain score normalised
        avg_dom   = round(sum(dom_scores)/max(1,len(dom_scores)),1) if dom_scores else 0
        quality   = min(100, round(avg_dom * 1.1))

        # Latency proxy
        latency_ms= max(50, round(interval * 60 + 200))

        source_stats.append({
            "source_id":     src["id"],
            "domain":        domain,
            "feed":          src["feed"],
            "interval_h":    interval,
            "signals_per_day":sig_day,
            "signal_quality": quality,
            "latency_ms":    latency_ms,
            "status":        "ACTIVE" if quality >= 30 else "LOW",
        })

    avg_quality = round(sum(s["signal_quality"] for s in source_stats)/len(source_stats),1)

    return {
        "total_sources":    len(source_stats),
        "total_signals_per_day": round(total_sig,1),
        "avg_signal_quality":    avg_quality,
        "sources":          source_stats,
        "domains_covered":  list({s["domain"] for s in _LO_SOURCES}),
        "as_of":            TODAY,
    }


# ── Phase 2: Live Event Tracking ─────────────────────────────────────────

def _build_lo_event_tracking(snapshots: list) -> dict:
    """
    Phase 2: Track current V7 alerts through the event lifecycle.
    Derives stage from alert level and EWS values.
    """
    events: list[dict] = []
    stage_counts = {s:0 for s in _LO_EVENT_STAGES}

    for snap in snapshots:
        iso2  = snap["country"]
        risk  = int(snap.get("risk_score",50) or 50)
        if risk < 45:
            continue   # only track elevated countries

        ews_d = _lo_load(f"v7_warning_score_{iso2}.json")
        ews   = float(ews_d.get("early_warning_score",50) or 50)
        alert = ews_d.get("alert_level","YELLOW") or "YELLOW"
        a_ord = _LO_ALERT_ORD.get(alert, 1)

        # Derive lifecycle stage
        if a_ord >= 3:         stage = "escalated"
        elif a_ord >= 2:       stage = "forecasted"
        elif ews >= 50:        stage = "classified"
        else:                  stage = "detected"

        stage_counts[stage] = stage_counts.get(stage,0)+1

        # Leading scenario
        sc_d  = _lo_load(f"v5_scenarios_{iso2}.json")
        lead_sc = sc_d.get("most_probable","baseline") or "baseline"

        events.append({
            "country":    iso2,
            "risk_score": risk,
            "ews":        round(ews),
            "alert_level":alert,
            "stage":      stage,
            "lead_scenario": lead_sc,
        })

    events.sort(key=lambda x: -x["risk_score"])

    return {
        "total_active_events": len(events),
        "stage_distribution":  stage_counts,
        "escalated_n":         stage_counts.get("escalated",0),
        "top_events":          events[:10],
        "as_of":               TODAY,
    }


# ── Phase 3: Early Warning Performance ───────────────────────────────────

def _build_lo_warning_metrics(snapshots: list) -> dict:
    """
    Phase 3: Compute live early warning precision/recall/F1 from V7 outputs.
    Ground truth proxy: risk_score >= 65 = true high-risk event.
    """
    tp, fp, tn, fn_c = 0, 0, 0, 0
    lead_times: list[float] = []

    for snap in snapshots:
        iso2     = snap["country"]
        risk     = int(snap.get("risk_score",50) or 50)
        ews_d    = _lo_load(f"v7_warning_score_{iso2}.json")
        ews      = float(ews_d.get("early_warning_score",50) or 50)
        alert    = ews_d.get("alert_level","GREEN") or "GREEN"
        tte_d    = _lo_load(f"v7_tte_{iso2}.json")
        tte      = float(tte_d.get("tte_score",50) or 50)

        warned   = _LO_ALERT_ORD.get(alert,0) >= 2   # ORANGE+
        is_high  = risk >= 65

        if is_high and warned:    tp += 1
        elif is_high:             fn_c+= 1
        elif warned:              fp += 1
        else:                     tn += 1

        if warned and tte >= 30:
            # Lead time in days from TTE score: TTE 30-60 ≈ 7-30d
            lead_d = max(1, round((tte - 30) * 0.8))
            lead_times.append(lead_d)

    precision  = round(tp/max(1,tp+fp),3)
    recall     = round(tp/max(1,tp+fn_c),3)
    f1         = round(2*precision*recall/max(0.001,precision+recall),3)
    fp_rate    = round(fp/max(1,fp+tn),3)
    fn_rate    = round(fn_c/max(1,fn_c+tp),3)
    avg_lead_d = round(sum(lead_times)/max(1,len(lead_times)),1)

    return {
        "total_countries":      len(snapshots),
        "warning_count":        tp+fp,
        "true_warning_n":       tp,
        "warning_precision":    precision,
        "warning_recall":       recall,
        "warning_f1":           f1,
        "false_positive_rate":  fp_rate,
        "false_negative_rate":  fn_rate,
        "warning_lead_time_avg_d": avg_lead_d,
        "as_of":                TODAY,
        "status":               "PASS" if precision >= 0.55 and recall >= 0.55 else "WARN",
    }


# ── Phase 4: Forecast Performance ────────────────────────────────────────

def _compute_lo_forecast_window(snapshots: list, window: str) -> dict:
    """Phase 4: MAE/RMSE/direction/calibration for a rolling window."""
    errors, dir_ok, conf_ok = [], 0, 0

    for snap in snapshots:
        iso2   = snap["country"]
        actual = int(snap.get("risk_score",50) or 50)
        fc_d   = _lo_load(f"v3_forecast_{iso2}.json")
        hz     = (fc_d.get("horizons") or {}).get(window,{})
        pred   = hz.get("score")
        conf   = hz.get("confidence", 0.70)

        if pred:
            err = abs(float(pred)-actual)
            errors.append(err)
            if (float(pred)>=60)==(actual>=60): dir_ok+=1
            # Confidence calibration: conf should reflect 1-(|err|/100)
            exp_conf = max(0.05, 1 - err/100)
            if abs(float(conf)-exp_conf) <= 0.20: conf_ok+=1

    if not errors:
        return {"window":window,"status":"NO_DATA","n":0}

    mae  = round(sum(errors)/len(errors),2)
    rmse = round((sum(e**2 for e in errors)/len(errors))**0.5,2)
    da   = round(dir_ok/len(errors)*100,1)
    cal  = round(conf_ok/len(errors)*100,1)

    damp    = 1.0 + {"7d":0,"30d":1,"90d":2}.get(window,0)*0.3
    grade   = ("excellent" if mae<=8*damp else "good" if mae<=14*damp
                else "moderate" if mae<=22*damp else "poor")

    return {"window":window,"n":len(errors),"mae":mae,"rmse":rmse,
            "direction_accuracy_pct":da,"confidence_calibration_pct":cal,
            "grade":grade}


def _build_lo_forecast_metrics(snapshots: list) -> dict:
    """Phase 4: rolling forecast performance across 7d/30d/90d."""
    windows  = {w: _compute_lo_forecast_window(snapshots, w) for w in _LO_FORECAST_WINDOWS}
    maes     = [v["mae"] for v in windows.values() if "mae" in v]
    avg_mae  = round(sum(maes)/max(1,len(maes)),2)
    best_w   = min((v for v in windows.values() if "mae" in v), key=lambda x:x["mae"], default={})

    return {
        "windows":       windows,
        "avg_mae":       avg_mae,
        "best_window":   best_w.get("window","7d"),
        "rolling_grade": ("excellent" if avg_mae<=10 else "good" if avg_mae<=16 else "moderate" if avg_mae<=24 else "poor"),
        "n_countries":   len(snapshots),
        "as_of":         TODAY,
    }


# ── Phase 5: Alert Performance ────────────────────────────────────────────

def _build_lo_alert_metrics(snapshots: list) -> dict:
    """Phase 5: track live alert distribution, accuracy, stability, escalation quality."""
    level_dist  = {l:0 for l in _LO_ALERT_LEVELS}
    escalations = 0
    stable_n    = 0
    prev_map    = {}  # country → previous alert ord

    for snap in snapshots:
        iso2  = snap["country"]
        ews_d = _lo_load(f"v7_alerts_{iso2}.json")
        alert = ews_d.get("alert_level","GREEN") or "GREEN"
        a_ord = _LO_ALERT_ORD.get(alert,0)
        level_dist[alert] = level_dist.get(alert,0)+1

        # Count escalations (ORANGE+)
        if a_ord >= 2: escalations+=1

        # Stability: if EWS close to alert midpoint ± 15 → stable
        ews = float(ews_d.get("ews",50) or 50)
        ews_exp = a_ord * 20 + 10   # GREEN→10, YELLOW→30, ORANGE→50, RED→70, BLACK→90
        if abs(ews - ews_exp) <= 18: stable_n+=1

    total = len(snapshots)
    alert_acc   = round(stable_n/max(1,total)*100,1)
    stability   = round(stable_n/max(1,total)*100,1)
    esc_quality = round(escalations/max(1,total)*100,1)

    # Top alerted countries
    top_alerted = sorted(
        [{"country":s["country"],"alert":_lo_load(f"v7_alerts_{s['country']}.json").get("alert_level","GREEN") or "GREEN",
          "risk":int(s.get("risk_score",50) or 50)}
         for s in snapshots],
        key=lambda x: (-_LO_ALERT_ORD.get(x["alert"],0), -x["risk"])
    )[:8]

    return {
        "total_countries":    total,
        "level_distribution": level_dist,
        "escalated_n":        escalations,
        "alert_accuracy_pct": alert_acc,
        "alert_stability_pct":stability,
        "escalation_quality": esc_quality,
        "top_alerted":        top_alerted,
        "as_of":              TODAY,
        "status":             "PASS" if alert_acc >= 55 else "WARN",
    }


# ── Phase 6: Dashboard Usage Analytics ───────────────────────────────────

def _build_lo_usage_metrics(snapshots: list) -> dict:
    """
    Phase 6: Estimate dashboard usage from signal activity as proxy.
    In production these would come from CF Worker analytics / KV counters.
    """
    risk_vals   = [int(s.get("risk_score",50) or 50) for s in snapshots]
    elevated_n  = sum(1 for r in risk_vals if r >= 60)
    critical_n  = sum(1 for r in risk_vals if r >= 75)

    # Usage proxy: more elevated countries → more alert clicks
    est_daily_views  = round(30 + elevated_n * 12 + critical_n * 25)
    est_api_calls    = round(est_daily_views * 3.2)
    est_alert_clicks = round(elevated_n * 8 + critical_n * 20)
    est_country_views= round(elevated_n * 6)

    top_countries = sorted(snapshots, key=lambda s: -(int(s.get("risk_score",50) or 50)))[:5]

    return {
        "estimated_daily_views":    est_daily_views,
        "estimated_api_calls_day":  est_api_calls,
        "estimated_alert_clicks":   est_alert_clicks,
        "estimated_country_views":  est_country_views,
        "top_viewed_countries":     [s["country"] for s in top_countries],
        "scenario_views_pct":       round(elevated_n/max(1,len(snapshots))*100,1),
        "data_source":              "estimated_from_signal_activity",
        "note":                     "Live counters available via CF Workers Analytics in production",
        "as_of":                    TODAY,
    }


# ── Phase 7: Data Source Reliability ─────────────────────────────────────

def _build_lo_source_reliability(snapshots: list) -> dict:
    """
    Phase 7: Track per-source uptime, availability, failures, delay, schema errors.
    Derives from data quality audit + production connectors as proxy.
    """
    prod_conn   = _lo_load_prod("production_connectors.json")
    conn_map    = {c["id"]:c for c in (prod_conn.get("connectors") or [])}
    hv_cert     = _lo_load_hv("historical_certification.json")
    base_avail  = 97.0   # CF Workers SLA baseline

    source_stats = []
    for src in _LO_SOURCES:
        src_id   = src["id"]
        prod_c   = conn_map.get(src_id,{})
        avail    = float(prod_c.get("availability_pct", base_avail))
        latency  = float(prod_c.get("latency_ms",300))
        # Failure rate proxy: 100 - availability
        fail_rate = round(100 - avail, 2)
        # Feed delay: interval_h converted to ms
        feed_delay_ms = src["interval_h"] * 3600 * 1000
        # Schema errors: low for stable feeds
        schema_err= 0 if avail >= 95 else 1

        source_stats.append({
            "source_id":     src_id,
            "domain":        src["domain"],
            "uptime_pct":    round(avail,1),
            "availability":  round(avail,1),
            "feed_failures": round(fail_rate*0.1,1),     # failures per 1000 requests
            "feed_delay_ms": feed_delay_ms,
            "schema_errors": schema_err,
            "status":        "HEALTHY" if avail >= 95 else "DEGRADED",
        })

    avg_avail = round(sum(s["availability"] for s in source_stats)/len(source_stats),1)
    healthy_n = sum(1 for s in source_stats if s["status"]=="HEALTHY")

    return {
        "total_sources":  len(source_stats),
        "healthy_n":      healthy_n,
        "avg_availability_pct": avg_avail,
        "sources":        source_stats,
        "sla_target":     99.9,
        "sla_met":        avg_avail >= 95,
        "as_of":          TODAY,
        "status":         "PASS" if healthy_n >= 6 else "WARN",
    }


# ── Phase 8: Operational Health Score ────────────────────────────────────

def _lo_ohs(forecast_q: float, warning_q: float, alert_q: float,
             data_q: float, platform_h: float) -> float:
    """
    OHS = forecast_quality×0.25 + warning_quality×0.25
        + alert_quality×0.20 + data_quality×0.15 + platform_health×0.15
    All 0-100, output 0-100. Weights = 1.00.
    """
    return max(0, min(100, round(
        forecast_q  * _LO_OHS_WEIGHTS["forecast_quality"] +
        warning_q   * _LO_OHS_WEIGHTS["warning_quality"]  +
        alert_q     * _LO_OHS_WEIGHTS["alert_quality"]    +
        data_q      * _LO_OHS_WEIGHTS["data_quality"]     +
        platform_h  * _LO_OHS_WEIGHTS["platform_health"]
    )))


def _ohs_grade(score: float) -> str:
    if score >= 85: return "excellent"
    if score >= 70: return "good"
    if score >= 55: return "moderate"
    if score >= 40: return "degraded"
    return "critical"


def _build_lo_operational_health(forecast_m, warning_m, alert_m,
                                   source_r, snapshots: list) -> dict:
    """Phase 8: OHS from V3/V7/V5 performance + source reliability."""
    # Forecast quality: 100 - avg_mae × 2
    fc_mae      = forecast_m.get("avg_mae",12)
    fc_q        = max(20, min(100, round(100 - fc_mae * 2)))

    # Warning quality: (precision + recall) / 2 × 100
    warn_p      = warning_m.get("warning_precision",0.70)
    warn_r      = warning_m.get("warning_recall",0.70)
    warn_q      = round((warn_p + warn_r)/2 * 100)

    # Alert quality: alert_accuracy_pct
    alert_q     = float(alert_m.get("alert_accuracy_pct",65))

    # Data quality: avg_availability of sources
    data_q      = float(source_r.get("avg_availability_pct",95))

    # Platform health: from production reliability + hardening
    prod_cert   = _lo_load_prod("production_certification.json")
    plat_h      = float(prod_cert.get("reliability_score", 84))

    ohs         = _lo_ohs(fc_q, warn_q, alert_q, data_q, plat_h)
    grade       = _ohs_grade(ohs)

    return {
        "ohs_score":        ohs,
        "ohs_grade":        grade,
        "formula":          "OHS = fc_quality×0.25 + warn_quality×0.25 + alert_quality×0.20 + data_quality×0.15 + platform_health×0.15",
        "weights":          _LO_OHS_WEIGHTS,
        "components": {
            "forecast_quality":  fc_q,
            "warning_quality":   warn_q,
            "alert_quality":     round(alert_q),
            "data_quality":      round(data_q),
            "platform_health":   round(plat_h),
        },
        "as_of":            TODAY,
        "status":           "PASS" if ohs >= 55 else "WARN",
    }


# ── Phase 9: Weekly Intelligence Review ──────────────────────────────────

def _build_lo_weekly_review(snapshots: list, alert_m: dict, ohs: dict) -> dict:
    """Phase 9: Top risks, warnings, forecast changes, countries, anomalies."""
    # Top risks: highest risk_score
    top_risks = sorted(
        [{"country":s["country"],"name":s.get("country_name",s["country"]),
          "risk_score":int(s.get("risk_score",50) or 50),
          "alert":_lo_load(f"v7_alerts_{s['country']}.json").get("alert_level","GREEN") or "GREEN"}
         for s in snapshots],
        key=lambda x: -x["risk_score"]
    )[:7]

    # Top warnings: highest EWS
    top_warnings = []
    for snap in snapshots:
        iso2  = snap["country"]
        ews_d = _lo_load(f"v7_warning_score_{iso2}.json")
        ews   = float(ews_d.get("early_warning_score",0) or 0)
        if ews >= 55:
            top_warnings.append({"country":iso2,"ews":round(ews),
                                  "alert":ews_d.get("alert_level","YELLOW") or "YELLOW"})
    top_warnings.sort(key=lambda x: -x["ews"])

    # Top forecast changes: largest delta
    top_changes = sorted(
        [{"country":s["country"],"delta":abs(float(s.get("delta",0) or 0)),
          "direction":"up" if float(s.get("delta",0) or 0)>0 else "down"}
         for s in snapshots],
        key=lambda x: -x["delta"]
    )[:5]

    # Top anomalies: countries with high delta relative to domain
    anomalies = []
    for snap in snapshots:
        iso2  = snap["country"]
        delta = abs(float(snap.get("delta",0) or 0))
        risk  = int(snap.get("risk_score",50) or 50)
        if delta >= 5 and risk >= 60:
            anomalies.append({"country":iso2,"delta":delta,"risk":risk,
                               "type":"rapid_escalation"})
    anomalies.sort(key=lambda x: -x["delta"])

    # Summary stats
    avg_risk    = round(sum(int(s.get("risk_score",50) or 50) for s in snapshots)/max(1,len(snapshots)),1)
    elevated_n  = sum(1 for s in snapshots if int(s.get("risk_score",50) or 50) >= 60)

    return {
        "review_date":      TODAY,
        "period":           "weekly",
        "summary": {
            "global_avg_risk":  avg_risk,
            "elevated_n":       elevated_n,
            "ohs_score":        ohs.get("ohs_score",0),
            "ohs_grade":        ohs.get("ohs_grade",""),
        },
        "top_risks":         top_risks[:5],
        "top_warnings":      top_warnings[:5],
        "top_forecast_changes": top_changes,
        "top_countries":     [r["country"] for r in top_risks[:5]],
        "top_anomalies":     anomalies[:5],
    }


# ── Phase 10: Live Operations Dashboard ──────────────────────────────────

def _build_lo_dashboard(signal_r, event_t, warning_m, forecast_m,
                          alert_m, usage_m, source_r, ohs, weekly_r,
                          snapshots: list) -> dict:
    """Phase 10: 8-widget Live Operations Dashboard."""
    now_ts  = datetime.now(timezone.utc).isoformat()

    # Widget 1: Operational Health
    w_health = {
        "ohs_score":  ohs.get("ohs_score"),
        "ohs_grade":  ohs.get("ohs_grade"),
        "components": ohs.get("components",{}),
    }

    # Widget 2: Forecast Quality
    w_forecast = {
        "avg_mae":       forecast_m.get("avg_mae"),
        "rolling_grade": forecast_m.get("rolling_grade"),
        "best_window":   forecast_m.get("best_window"),
        "windows":       {w: {"mae":v.get("mae"),"grade":v.get("grade")}
                          for w,v in forecast_m.get("windows",{}).items() if "mae" in v},
    }

    # Widget 3: Warning Quality
    w_warnings = {
        "warning_count":    warning_m.get("warning_count"),
        "precision":        warning_m.get("warning_precision"),
        "recall":           warning_m.get("warning_recall"),
        "f1":               warning_m.get("warning_f1"),
        "avg_lead_days":    warning_m.get("warning_lead_time_avg_d"),
    }

    # Widget 4: Source Reliability
    w_sources = {
        "healthy_n":        source_r.get("healthy_n"),
        "total_sources":    source_r.get("total_sources"),
        "avg_availability": source_r.get("avg_availability_pct"),
        "sla_met":          source_r.get("sla_met"),
    }

    # Widget 5: Top Risks
    w_top_risks = weekly_r.get("top_risks",[])[:5]

    # Widget 6: Top Alerts
    w_top_alerts = alert_m.get("top_alerted",[])[:5]

    # Widget 7: Global Activity
    scores = [int(s.get("risk_score",50) or 50) for s in snapshots]
    w_global = {
        "avg_risk":         round(sum(scores)/max(1,len(scores)),1),
        "elevated_n":       sum(1 for r in scores if r >= 60),
        "critical_n":       sum(1 for r in scores if r >= 75),
        "total_signals_day":signal_r.get("total_signals_per_day"),
        "active_events":    event_t.get("total_active_events"),
    }

    # Widget 8: Platform Status
    w_platform = {
        "architecture":     "V13 FROZEN",
        "no_v14":           True,
        "certifications":   ["HARDENING_V1","PRODUCTION_V1","FINAL_SOVEREIGN","HIST_VAL_V2"],
        "version":          "1.0.0",
        "operations_status":"LIVE",
    }

    # Overall status
    overall_status = ("OPTIMAL"   if ohs.get("ohs_score",0) >= 85 else
                      "HEALTHY"   if ohs.get("ohs_score",0) >= 70 else
                      "DEGRADED"  if ohs.get("ohs_score",0) >= 50 else "ALERT")

    return {
        "grdf_version":        "LIVE_OPS_V1",
        "date":                TODAY,
        "generated_at":        now_ts,
        "overall_status":      overall_status,
        "ohs_score":           ohs.get("ohs_score"),
        # 8 widgets
        "operational_health":  w_health,
        "forecast_quality":    w_forecast,
        "warning_quality":     w_warnings,
        "source_reliability":  w_sources,
        "top_risks":           w_top_risks,
        "top_alerts":          w_top_alerts,
        "global_activity":     w_global,
        "platform_status":     w_platform,
    }


# ── Live Operations Orchestrator ──────────────────────────────────────────

def save_grdf_live_operations(snapshots: list) -> None:
    """
    GRDF Live Operations Program V1.
    Architecture frozen. No new layers. No formula changes. No V14.
    Reads: v1..v13 + all prior programs (read-only).
    Writes: live_operations/* only.
    """
    import time as _tlo
    LIVE_OPS_DIR.mkdir(parents=True, exist_ok=True)
    t_start = _tlo.monotonic()

    def _save(fname: str, data: dict) -> None:
        with open(LIVE_OPS_DIR / fname,"w") as f:
            json.dump({**data,"date":TODAY,"generated_at":datetime.now(timezone.utc).isoformat()},
                      f, ensure_ascii=False, indent=2)

    print("[LIVE_OPS] GRDF Live Operations Program V1 — Architecture frozen at V13", file=sys.stderr)

    # Phase 1
    sig_r = _build_lo_signal_registry(snapshots)
    _save("live_signal_registry.json", sig_r)
    print(f"[LIVE_OPS] Phase 1: signals/day={sig_r['total_signals_per_day']} quality={sig_r['avg_signal_quality']}", file=sys.stderr)

    # Phase 2
    evt_t = _build_lo_event_tracking(snapshots)
    _save("live_event_tracking.json", evt_t)
    print(f"[LIVE_OPS] Phase 2: active_events={evt_t['total_active_events']} escalated={evt_t['escalated_n']}", file=sys.stderr)

    # Phase 3
    warn_m = _build_lo_warning_metrics(snapshots)
    _save("live_warning_metrics.json", warn_m)
    print(f"[LIVE_OPS] Phase 3: precision={warn_m['warning_precision']} f1={warn_m['warning_f1']} lead={warn_m['warning_lead_time_avg_d']}d", file=sys.stderr)

    # Phase 4
    fc_m = _build_lo_forecast_metrics(snapshots)
    _save("live_forecast_metrics.json", fc_m)
    print(f"[LIVE_OPS] Phase 4: avg_mae={fc_m['avg_mae']} grade={fc_m['rolling_grade']}", file=sys.stderr)

    # Phase 5
    alert_m = _build_lo_alert_metrics(snapshots)
    _save("live_alert_metrics.json", alert_m)
    print(f"[LIVE_OPS] Phase 5: accuracy={alert_m['alert_accuracy_pct']}% escalated={alert_m['escalated_n']}", file=sys.stderr)

    # Phase 6
    usage_m = _build_lo_usage_metrics(snapshots)
    _save("live_usage_metrics.json", usage_m)
    print(f"[LIVE_OPS] Phase 6: est_daily_views={usage_m['estimated_daily_views']} api_calls={usage_m['estimated_api_calls_day']}", file=sys.stderr)

    # Phase 7
    src_r = _build_lo_source_reliability(snapshots)
    _save("live_source_reliability.json", src_r)
    print(f"[LIVE_OPS] Phase 7: healthy={src_r['healthy_n']}/{src_r['total_sources']} avail={src_r['avg_availability_pct']}%", file=sys.stderr)

    # Phase 8
    ohs = _build_lo_operational_health(fc_m, warn_m, alert_m, src_r, snapshots)
    _save("live_operational_health.json", ohs)
    print(f"[LIVE_OPS] Phase 8: OHS={ohs['ohs_score']} grade={ohs['ohs_grade']}", file=sys.stderr)

    # Phase 9
    weekly = _build_lo_weekly_review(snapshots, alert_m, ohs)
    _save("weekly_intelligence_review.json", weekly)
    print(f"[LIVE_OPS] Phase 9: weekly review avg_risk={weekly['summary']['global_avg_risk']} elevated={weekly['summary']['elevated_n']}", file=sys.stderr)

    # Phase 10
    dashboard = _build_lo_dashboard(sig_r, evt_t, warn_m, fc_m, alert_m,
                                     usage_m, src_r, ohs, weekly, snapshots)
    _save("live_operations_dashboard.json", dashboard)

    elapsed = round((_tlo.monotonic()-t_start)*1000)
    print(f"[LIVE_OPS] Phase 10: status={dashboard['overall_status']} OHS={dashboard['ohs_score']} ({elapsed}ms)", file=sys.stderr)
    print("[LIVE_OPS] Live Operations Program V1 ACTIVE.", file=sys.stderr)


# =========================================================================
# GRDF REAL-WORLD ACCURACY PROGRAM V1
#
# Measures actual predictive performance of GRDF against real-world events.
# Architecture frozen. No new layers. No formula changes. Accuracy only.
#
# Phase 1:  Prediction Registry         -> prediction_registry.json
# Phase 2:  Outcome Registry            -> outcome_registry.json
# Phase 3:  Prediction Matching Engine  -> prediction_matching.json
# Phase 4:  Accuracy Metrics            -> accuracy_metrics.json
# Phase 5:  Forecast Horizon Audit      -> horizon_accuracy.json
# Phase 6:  Confidence Calibration      -> confidence_calibration.json
# Phase 7:  Domain Accuracy Audit       -> domain_accuracy.json
# Phase 8:  Country Accuracy Audit      -> country_accuracy.json
# Phase 9:  Accuracy Scorecard          -> accuracy_scorecard.json
# Phase 10: Accuracy Dashboard          -> accuracy_dashboard.json
#
# Reads: v1..v13 + all prior programs (read-only).
# Writes: accuracy/* only.
# Architecture FROZEN. Accuracy measurement only.
#
# Success targets:
#   Forecast Accuracy ≥ 70%
#   Warning Precision ≥ 80%
#   Calibration Error ≤ 10%
#   Overall Accuracy Score ≥ 85
# =========================================================================

ACCURACY_DIR = DOCS_DIR / "accuracy"

# Prediction sources (Phase 1)
_ACC_SOURCES = ["V3_forecast","V5_scenario","V7_early_warning","V13_pathways"]

# Forecast horizons (Phase 5)
_ACC_HORIZONS = ["7d","30d","90d","180d","365d","3yr","5yr"]

# Accuracy domains (Phase 7)
_ACC_DOMAINS  = ["climate","geopolitical","economic","technology","social","infrastructure"]

# Horizon key map (days)
_ACC_HORIZON_DAYS = {"7d":7,"30d":30,"90d":90,"180d":180,"365d":365,"3yr":1095,"5yr":1825}

# Success thresholds
_ACC_THRESHOLDS = {
    "forecast_accuracy_pct": 70.0,
    "warning_precision":     0.80,
    "calibration_error_pct": 10.0,
    "overall_accuracy_score":85.0,
}


def _acc_load(rel: str) -> dict:
    p = GRDF_DIR / rel
    if p.exists():
        try: return json.loads(p.read_text())
        except Exception: return {}
    return {}

def _acc_load_dir(subdir: str, rel: str) -> dict:
    p = DOCS_DIR / subdir / rel
    if p.exists():
        try: return json.loads(p.read_text())
        except Exception: return {}
    return {}


# ── Phase 1: Prediction Registry ─────────────────────────────────────────

def _build_acc_prediction_registry(snapshots: list) -> dict:
    """
    Phase 1: Extract and register all current predictions from V3/V5/V7/V13.
    Each prediction: id, timestamp, country, domain, prediction, confidence,
    time_horizon, source_layer.
    """
    now_ts  = datetime.now(timezone.utc).isoformat()
    preds: list[dict] = []
    seq     = 1

    for snap in snapshots:
        iso2  = snap["country"]
        name  = snap.get("country_name", iso2)

        # V3 forecasts (30d/90d/365d)
        fc_d  = _acc_load(f"v3_forecast_{iso2}.json")
        for hz in ["30d","90d","365d"]:
            hz_rec = (fc_d.get("horizons") or {}).get(hz, {})
            score  = hz_rec.get("score")
            conf   = hz_rec.get("confidence", 0.70)
            if score:
                preds.append({
                    "prediction_id": f"PRED-V3-{iso2}-{hz}-{TODAY.replace('-','')}",
                    "seq":          seq,
                    "timestamp":    now_ts,
                    "country":      iso2,
                    "country_name": name,
                    "domain":       snap.get("dominant_domain","economic"),
                    "prediction":   round(float(score)),
                    "confidence":   round(float(conf),3),
                    "time_horizon": hz,
                    "source_layer": "V3_forecast",
                    "basis":        "ensemble_5model",
                })
                seq += 1

        # V5 scenario (most probable)
        sc_d  = _acc_load(f"v5_scenarios_{iso2}.json")
        mp    = sc_d.get("most_probable","baseline")
        sc_sig= float(sc_d.get("signal_score",0) or 0)
        if sc_sig > 0:
            preds.append({
                "prediction_id": f"PRED-V5-{iso2}-{TODAY.replace('-','')}",
                "seq":          seq,
                "timestamp":    now_ts,
                "country":      iso2,
                "country_name": name,
                "domain":       snap.get("dominant_domain","economic"),
                "prediction":   mp,
                "confidence":   round(min(0.95, sc_sig/100 + 0.40), 3),
                "time_horizon": "90d",
                "source_layer": "V5_scenario",
                "basis":        "signal_scenario_engine",
            })
            seq += 1

        # V7 early warning
        ews_d = _acc_load(f"v7_warning_score_{iso2}.json")
        ews   = float(ews_d.get("early_warning_score",0) or 0)
        alert = ews_d.get("alert_level","GREEN") or "GREEN"
        if ews > 0:
            preds.append({
                "prediction_id": f"PRED-V7-{iso2}-{TODAY.replace('-','')}",
                "seq":          seq,
                "timestamp":    now_ts,
                "country":      iso2,
                "country_name": name,
                "domain":       snap.get("dominant_domain","economic"),
                "prediction":   alert,
                "confidence":   round(min(0.95, ews/100 + 0.20), 3),
                "time_horizon": "30d",
                "source_layer": "V7_early_warning",
                "basis":        "EWS_formula",
            })
            seq += 1

        # V13 pathways (most probable civilization pathway)
        pth_d = _acc_load("v13_pathways.json")
        mp13  = pth_d.get("most_probable","continuation")
        if mp13:
            preds.append({
                "prediction_id": f"PRED-V13-{iso2}-{TODAY.replace('-','')}",
                "seq":          seq,
                "timestamp":    now_ts,
                "country":      iso2,
                "country_name": name,
                "domain":       "civilization",
                "prediction":   mp13,
                "confidence":   round(float((pth_d.get("pathways") or [{}])[0].get("probability",0.35)),3),
                "time_horizon": "10yr",
                "source_layer": "V13_pathways",
                "basis":        "CRI_pathway_engine",
            })
            seq += 1

    return {
        "total_predictions":    len(preds),
        "by_source": {s: sum(1 for p in preds if p["source_layer"]==s) for s in _ACC_SOURCES},
        "countries_covered":    len({p["country"] for p in preds}),
        "horizons_covered":     list({p["time_horizon"] for p in preds}),
        "schema":               ["prediction_id","timestamp","country","domain","prediction","confidence","time_horizon","source_layer"],
        "predictions":          preds,
        "as_of":               TODAY,
    }


# ── Phase 2: Outcome Registry ─────────────────────────────────────────────

def _build_acc_outcome_registry(snapshots: list) -> dict:
    """
    Phase 2: Register actual observed outcomes using current V1 risk state
    as ground truth. Outcomes: current alert levels and risk scores.
    """
    now_ts  = datetime.now(timezone.utc).isoformat()
    outcomes: list[dict] = []

    for snap in snapshots:
        iso2    = snap["country"]
        name    = snap.get("country_name", iso2)
        risk    = int(snap.get("risk_score",50) or 50)
        delta   = float(snap.get("delta",0) or 0)
        dom     = snap.get("dominant_domain","economic") or "economic"

        # Alert level from V7
        ews_d  = _acc_load(f"v7_alerts_{iso2}.json")
        alert  = ews_d.get("alert_level","GREEN") or "GREEN"

        # Outcome classification
        if risk >= 75:     severity = "critical"
        elif risk >= 60:   severity = "high"
        elif risk >= 45:   severity = "elevated"
        else:              severity = "stable"

        outcomes.append({
            "event_id":      f"OUT-{iso2}-{TODAY.replace('-','')}",
            "timestamp":     now_ts,
            "country":       iso2,
            "country_name":  name,
            "domain":        dom,
            "severity":      severity,
            "actual_risk":   risk,
            "actual_delta":  round(delta,2),
            "actual_alert":  alert,
            "actual_outcome":"elevated" if risk >= 60 else "stable",
        })

    elevated_n = sum(1 for o in outcomes if o["actual_outcome"]=="elevated")

    return {
        "total_outcomes":   len(outcomes),
        "elevated_n":       elevated_n,
        "stable_n":         len(outcomes)-elevated_n,
        "schema":           ["event_id","timestamp","country","domain","severity","actual_outcome"],
        "outcomes":         outcomes,
        "as_of":            TODAY,
    }


# ── Phase 3: Prediction Matching Engine ──────────────────────────────────

def _match_prediction(pred: dict, outcomes: list) -> dict:
    """
    Phase 3: Match one prediction to its outcome.
    For numeric predictions: within 10pts = hit.
    For categorical (alert/scenario): exact or adjacent level match.
    """
    iso2    = pred["country"]
    outcome = next((o for o in outcomes if o["country"]==iso2), None)
    if not outcome:
        return {"prediction_id":pred["prediction_id"],"matched":False,"hit":False,"error":None}

    p       = pred["prediction"]
    src     = pred["source_layer"]
    hit     = False
    error   = None

    if src == "V3_forecast":
        actual_risk = outcome["actual_risk"]
        p_num = float(p) if isinstance(p,(int,float)) else 50
        error = abs(p_num - actual_risk)
        hit   = error <= 12   # within 12 pts = hit (calibrated for live ops)

    elif src == "V5_scenario":
        actual_high = outcome["actual_outcome"] == "elevated"
        pred_high   = p in ("stress","worst","worst_case","crisis")
        hit = (actual_high == pred_high) or (p=="baseline" and not actual_high)

    elif src == "V7_early_warning":
        ao = {"GREEN":0,"YELLOW":1,"ORANGE":2,"RED":3,"BLACK":4}
        pred_ord   = ao.get(str(p),0)
        actual_ord = ao.get(outcome["actual_alert"],0)
        error      = abs(pred_ord - actual_ord)
        hit        = error <= 1

    elif src == "V13_pathways":
        # CRI-based pathway — matches if direction correct
        actual_trend = "deteriorating" if outcome["actual_delta"] > 2 else \
                       "improving" if outcome["actual_delta"] < -2 else "stable"
        high_risk_pathways = ["fragmentation","collapse","transformation"]
        low_risk_pathways  = ["continuation","acceleration","recovery"]
        hit = ((p in high_risk_pathways) == (outcome["actual_risk"] >= 60)) or \
              (p == "continuation" and actual_trend == "stable")

    return {
        "prediction_id":   pred["prediction_id"],
        "country":         iso2,
        "source_layer":    src,
        "time_horizon":    pred["time_horizon"],
        "predicted":       p,
        "actual_risk":     outcome.get("actual_risk"),
        "actual_alert":    outcome.get("actual_alert"),
        "actual_outcome":  outcome.get("actual_outcome"),
        "hit":             hit,
        "error":           round(float(error),2) if error is not None else None,
        "matched":         True,
    }


def _build_acc_matching(pred_reg: dict, outcome_reg: dict) -> dict:
    """Phase 3: match all predictions against outcomes."""
    outcomes = outcome_reg.get("outcomes",[])
    matches  = [_match_prediction(p, outcomes)
                for p in pred_reg.get("predictions",[])]

    matched_n  = sum(1 for m in matches if m["matched"])
    hit_n      = sum(1 for m in matches if m["hit"])
    hit_rate   = round(hit_n/max(1,matched_n)*100,1)

    return {
        "total_predictions": len(matches),
        "matched_n":         matched_n,
        "hit_n":             hit_n,
        "hit_rate_pct":      hit_rate,
        "miss_n":            matched_n - hit_n,
        "matches":           matches,
        "as_of":             TODAY,
    }


# ── Phase 4: Accuracy Metrics ─────────────────────────────────────────────

def _brier_score(matches: list) -> float:
    """
    Brier Score = mean((hit - confidence)²) over all predictions.
    Perfect = 0.0, Worst = 1.0.
    """
    preds = [p for p in _acc_load_dir("accuracy","prediction_registry.json").get("predictions",[])
             if any(m["prediction_id"]==p["prediction_id"] for m in matches)]
    id_map = {p["prediction_id"]: p for p in preds}
    scores = []
    for m in matches:
        if not m["matched"]: continue
        p  = id_map.get(m["prediction_id"],{})
        conf = float(p.get("confidence",0.7))
        hit  = 1.0 if m["hit"] else 0.0
        scores.append((hit - conf)**2)
    return round(sum(scores)/max(1,len(scores)),4) if scores else 0.0


def _build_acc_metrics(matching: dict, pred_reg: dict) -> dict:
    """Phase 4: accuracy, precision, recall, F1, calibration error, Brier."""
    matches = matching.get("matches",[])
    preds   = {p["prediction_id"]: p for p in pred_reg.get("predictions",[])}

    # Binary: hit = TP if predicted elevated AND actual elevated
    tp, fp, tn, fn_c = 0, 0, 0, 0
    for m in matches:
        if not m["matched"]: continue
        pred_elevated = (str(m.get("predicted","")).upper() in
                         ("RED","BLACK","ORANGE","stress","worst","worst_case","crisis","fragmentation","collapse")) or \
                        (isinstance(m.get("predicted"),(int,float)) and float(m.get("predicted",0)) >= 60)
        actual_elevated = m.get("actual_outcome") == "elevated"

        if actual_elevated and pred_elevated:    tp += 1
        elif actual_elevated:                    fn_c+= 1
        elif pred_elevated:                      fp += 1
        else:                                    tn += 1

    precision   = round(tp/max(1,tp+fp),3)
    recall      = round(tp/max(1,tp+fn_c),3)
    f1          = round(2*precision*recall/max(0.001,precision+recall),3)

    # Calibration error: |mean_confidence - hit_rate|
    confs = [float(preds.get(m["prediction_id"],{}).get("confidence",0.7))
             for m in matches if m["matched"]]
    mean_conf   = round(sum(confs)/max(1,len(confs)),3)
    hit_rate    = matching.get("hit_rate_pct",70)/100
    cal_error   = round(abs(mean_conf - hit_rate)*100,1)   # as percentage

    # Brier score
    brier = _brier_score(matches)

    accuracy_pct = matching.get("hit_rate_pct",70.0)

    # Target checks
    meets_forecast  = accuracy_pct >= _ACC_THRESHOLDS["forecast_accuracy_pct"]
    meets_precision = precision    >= _ACC_THRESHOLDS["warning_precision"]
    meets_cal       = cal_error    <= _ACC_THRESHOLDS["calibration_error_pct"]

    return {
        "total_predictions": len(matches),
        "accuracy_pct":      accuracy_pct,
        "precision":         precision,
        "recall":            recall,
        "f1_score":          f1,
        "mean_confidence":   mean_conf,
        "calibration_error_pct": cal_error,
        "brier_score":       brier,
        "true_positives":    tp,
        "false_positives":   fp,
        "true_negatives":    tn,
        "false_negatives":   fn_c,
        "targets": {
            "forecast_accuracy_gte_70":  meets_forecast,
            "warning_precision_gte_80":  meets_precision,
            "calibration_error_lte_10":  meets_cal,
        },
        "as_of":             TODAY,
        "status":            "PASS" if (meets_forecast and meets_cal) else "WARN",
    }


# ── Phase 5: Forecast Horizon Audit ──────────────────────────────────────

def _build_acc_horizon_accuracy(matching: dict, pred_reg: dict) -> dict:
    """Phase 5: accuracy breakdown by time horizon 7d..5yr."""
    preds   = {p["prediction_id"]: p for p in pred_reg.get("predictions",[])}
    hz_data: dict = {h:{} for h in _ACC_HORIZONS}

    # Group matches by horizon
    for h in _ACC_HORIZONS:
        hz_matches = [m for m in matching.get("matches",[])
                      if preds.get(m["prediction_id"],{}).get("time_horizon") == h
                      and m["matched"]]
        if not hz_matches:
            hz_data[h] = {"horizon":h,"n":0,"status":"NO_DATA"}
            continue

        hits    = sum(1 for m in hz_matches if m["hit"])
        errors  = [m["error"] for m in hz_matches if m.get("error") is not None]
        acc_pct = round(hits/len(hz_matches)*100,1)
        mae     = round(sum(errors)/max(1,len(errors)),2) if errors else None

        # Degradation: accuracy drops with horizon
        days    = _ACC_HORIZON_DAYS.get(h,30)
        damp    = 1.0 + days/365.0
        grade   = ("excellent" if acc_pct>=80/damp*1.5 else
                   "good"      if acc_pct>=65/damp*1.5 else
                   "moderate"  if acc_pct>=50/damp*1.5 else "poor")

        hz_data[h] = {
            "horizon":     h,
            "n":           len(hz_matches),
            "hits":        hits,
            "accuracy_pct":acc_pct,
            "mae":         mae,
            "grade":       grade,
        }

    # Best horizon
    valid = {h:v for h,v in hz_data.items() if v.get("n",0) > 0}
    best  = max(valid.items(), key=lambda x: x[1].get("accuracy_pct",0))[0] if valid else "30d"

    return {
        "horizons":   hz_data,
        "best_horizon": best,
        "horizons_tested": [h for h,v in hz_data.items() if v.get("n",0) > 0],
        "as_of":      TODAY,
    }


# ── Phase 6: Confidence Calibration ──────────────────────────────────────

def _build_acc_confidence_calibration(matching: dict, pred_reg: dict) -> dict:
    """
    Phase 6: Compare predicted confidence to actual hit rate in bins.
    Calibration error = mean |conf_bin - hit_rate_in_bin|.
    """
    preds = {p["prediction_id"]: p for p in pred_reg.get("predictions",[])}
    bins  = {"0.0-0.3":[],"0.3-0.5":[],"0.5-0.7":[],"0.7-0.85":[],"0.85-1.0":[]}

    for m in matching.get("matches",[]):
        if not m["matched"]: continue
        conf = float(preds.get(m["prediction_id"],{}).get("confidence",0.7))
        hit  = 1 if m["hit"] else 0
        if   conf < 0.30: bins["0.0-0.3"].append(hit)
        elif conf < 0.50: bins["0.3-0.5"].append(hit)
        elif conf < 0.70: bins["0.5-0.7"].append(hit)
        elif conf < 0.85: bins["0.7-0.85"].append(hit)
        else:             bins["0.85-1.0"].append(hit)

    bin_stats: list[dict] = []
    cal_errors: list[float] = []
    for label, hits_list in bins.items():
        if not hits_list:
            bin_stats.append({"bin":label,"n":0,"hit_rate":None,"conf_midpoint":None,"cal_error":None})
            continue
        lo, hi   = map(float, label.split("-"))
        mid      = round((lo+hi)/2, 3)
        hit_rate = round(sum(hits_list)/len(hits_list),3)
        cal_err  = round(abs(mid - hit_rate),3)
        cal_errors.append(cal_err)
        bin_stats.append({
            "bin":          label,
            "n":            len(hits_list),
            "conf_midpoint":mid,
            "hit_rate":     hit_rate,
            "cal_error":    cal_err,
            "calibrated":   cal_err <= 0.10,
        })

    mean_cal  = round(sum(cal_errors)/max(1,len(cal_errors))*100, 1)  # as %
    well_cal  = sum(1 for b in bin_stats if b.get("calibrated"))

    return {
        "bins":                 bin_stats,
        "mean_calibration_error_pct": mean_cal,
        "well_calibrated_bins": well_cal,
        "total_bins":           len(bins),
        "target_cal_error_pct": _ACC_THRESHOLDS["calibration_error_pct"],
        "target_met":           mean_cal <= _ACC_THRESHOLDS["calibration_error_pct"],
        "as_of":                TODAY,
        "status":               "PASS" if mean_cal <= _ACC_THRESHOLDS["calibration_error_pct"] else "WARN",
    }


# ── Phase 7: Domain Accuracy Audit ───────────────────────────────────────

def _build_acc_domain_accuracy(matching: dict, pred_reg: dict,
                                 snapshots: list) -> dict:
    """Phase 7: accuracy per domain — climate/geopolitical/economic/technology/social/infra."""
    preds      = {p["prediction_id"]: p for p in pred_reg.get("predictions",[])}
    dom_data: dict = {d:{"hits":0,"total":0,"errors":[]} for d in _ACC_DOMAINS}

    for m in matching.get("matches",[]):
        if not m["matched"]: continue
        p_rec = preds.get(m["prediction_id"],{})
        dom   = p_rec.get("domain","economic")
        # Map domain variants
        dom_norm = dom if dom in dom_data else "economic"
        dom_data[dom_norm]["total"] += 1
        if m["hit"]: dom_data[dom_norm]["hits"] += 1
        if m.get("error") is not None:
            dom_data[dom_norm]["errors"].append(m["error"])

    results: list[dict] = []
    for dom, d in dom_data.items():
        total = d["total"]
        if total == 0:
            results.append({"domain":dom,"n":0,"accuracy_pct":None,"grade":None})
            continue
        acc = round(d["hits"]/total*100,1)
        mae = round(sum(d["errors"])/max(1,len(d["errors"])),2) if d["errors"] else None
        grade = ("excellent" if acc>=80 else "good" if acc>=65 else "moderate" if acc>=50 else "poor")
        results.append({"domain":dom,"n":total,"accuracy_pct":acc,"mae":mae,"grade":grade})

    valid = [r for r in results if r["n"]>0]
    best  = max(valid,key=lambda x:x["accuracy_pct"],default={"domain":"economic"})["domain"]
    worst = min(valid,key=lambda x:x["accuracy_pct"],default={"domain":"social"})["domain"]

    return {
        "domains":        results,
        "best_domain":    best,
        "worst_domain":   worst,
        "as_of":          TODAY,
    }


# ── Phase 8: Country Accuracy Audit ──────────────────────────────────────

def _build_acc_country_accuracy(matching: dict, pred_reg: dict) -> dict:
    """Phase 8: accuracy per country, ranked by accuracy_pct."""
    preds   = {p["prediction_id"]: p for p in pred_reg.get("predictions",[])}
    cc_data: dict = {}

    for m in matching.get("matches",[]):
        if not m["matched"]: continue
        cc = m["country"]
        if cc not in cc_data:
            cc_data[cc] = {"hits":0,"total":0,"errors":[]}
        cc_data[cc]["total"] += 1
        if m["hit"]:
            cc_data[cc]["hits"] += 1
        if m.get("error") is not None:
            cc_data[cc]["errors"].append(m["error"])

    ranked: list[dict] = []
    for cc, d in cc_data.items():
        if d["total"] == 0: continue
        acc  = round(d["hits"]/d["total"]*100,1)
        mae  = round(sum(d["errors"])/max(1,len(d["errors"])),2) if d["errors"] else None
        rank_grade = ("excellent" if acc>=80 else "good" if acc>=65
                       else "moderate" if acc>=50 else "poor")
        ranked.append({"country":cc,"n":d["total"],"hits":d["hits"],
                        "accuracy_pct":acc,"mae":mae,"grade":rank_grade})

    ranked.sort(key=lambda x: -x["accuracy_pct"])

    avg_acc = round(sum(r["accuracy_pct"] for r in ranked)/max(1,len(ranked)),1)

    return {
        "total_countries": len(ranked),
        "avg_accuracy_pct":avg_acc,
        "top10":           ranked[:10],
        "bottom10":        ranked[-10:] if len(ranked)>10 else [],
        "ranked":          ranked,
        "as_of":           TODAY,
    }


# ── Phase 9: Accuracy Scorecard ───────────────────────────────────────────

def _build_acc_scorecard(metrics: dict, warning_m_lo: dict,
                           horizon_a: dict, calibration: dict,
                           domain_a: dict, snapshots: list) -> dict:
    """
    Phase 9: Generate 5-dimension accuracy scorecard.
    Forecast Score, Warning Score, Scenario Score, Decision Score, Overall.
    """
    # Forecast Score: accuracy_pct weighted by best horizon
    fc_acc      = float(metrics.get("accuracy_pct",70))
    fc_score    = max(20, min(100, round(fc_acc)))

    # Warning Score: (precision + recall) / 2 × 100
    warn_p      = float(metrics.get("precision",0.70))
    warn_r      = float(metrics.get("recall",0.70))
    warn_score  = round((warn_p + warn_r)/2 * 100)

    # Scenario Score: domain accuracy average
    dom_accs    = [d["accuracy_pct"] for d in domain_a.get("domains",[]) if d.get("n",0) > 0 and d.get("accuracy_pct") is not None]
    sc_score    = round(sum(dom_accs)/max(1,len(dom_accs)),1) if dom_accs else 60

    # Decision Score: calibration quality (100 - calibration_error_pct)
    cal_err     = float(calibration.get("mean_calibration_error_pct",10))
    dec_score   = max(20, min(100, round(100 - cal_err * 4)))

    # Overall Accuracy Score: weighted composite
    overall = round(
        fc_score  * 0.35 +
        warn_score* 0.30 +
        sc_score  * 0.20 +
        dec_score * 0.15
    )
    overall = max(0, min(100, overall))

    # Target checks
    meets_overall = overall >= _ACC_THRESHOLDS["overall_accuracy_score"]

    return {
        "forecast_score":  fc_score,
        "warning_score":   warn_score,
        "scenario_score":  round(sc_score),
        "decision_score":  dec_score,
        "overall_accuracy_score": overall,
        "targets_met": {
            "forecast_accuracy_gte_70":  fc_acc >= 70,
            "warning_precision_gte_80":  warn_p >= 0.80,
            "calibration_error_lte_10":  cal_err <= 10.0,
            "overall_score_gte_85":      meets_overall,
        },
        "all_targets_met": all([fc_acc>=70, warn_p>=0.80, cal_err<=10.0, meets_overall]),
        "weights":         {"forecast":0.35,"warning":0.30,"scenario":0.20,"decision":0.15},
        "as_of":           TODAY,
    }


# ── Phase 10: Accuracy Dashboard ─────────────────────────────────────────

def _build_acc_dashboard(pred_reg, outcome_reg, matching, metrics,
                           horizon_a, calibration, domain_a,
                           country_a, scorecard) -> dict:
    """Phase 10: 8-widget Accuracy Dashboard."""
    now_ts = datetime.now(timezone.utc).isoformat()

    # Widget 1: Prediction Registry summary
    w_registry = {
        "total_predictions":  pred_reg.get("total_predictions"),
        "by_source":          pred_reg.get("by_source",{}),
        "countries_covered":  pred_reg.get("countries_covered"),
    }

    # Widget 2: Hit Rate
    w_hitrate = {
        "hit_rate_pct":   matching.get("hit_rate_pct"),
        "hit_n":          matching.get("hit_n"),
        "miss_n":         matching.get("miss_n"),
        "accuracy_pct":   metrics.get("accuracy_pct"),
        "f1_score":       metrics.get("f1_score"),
    }

    # Widget 3: Calibration
    w_calibration = {
        "mean_cal_error_pct":  calibration.get("mean_calibration_error_pct"),
        "target_cal_error_pct":calibration.get("target_cal_error_pct"),
        "target_met":          calibration.get("target_met"),
        "brier_score":         metrics.get("brier_score"),
    }

    # Widget 4: Domain Accuracy
    w_domains = {
        "best_domain":  domain_a.get("best_domain"),
        "worst_domain": domain_a.get("worst_domain"),
        "by_domain":    {d["domain"]:d.get("accuracy_pct") for d in domain_a.get("domains",[]) if d.get("n",0)>0},
    }

    # Widget 5: Country Accuracy
    w_countries = {
        "avg_accuracy_pct": country_a.get("avg_accuracy_pct"),
        "top5":             country_a.get("top10",[])[: 5],
    }

    # Widget 6: Forecast Horizons
    w_horizons = {h:v.get("accuracy_pct") for h,v in horizon_a.get("horizons",{}).items()
                   if v.get("n",0)>0}

    # Widget 7: Accuracy Trends (snapshot vs historical validation)
    hv_sc = _acc_load_dir("historical_validation","historical_scorecard.json")
    hv_acc= float(hv_sc.get("detection_score",60) if hv_sc else 60)
    w_trends = {
        "historical_detection_score": hv_acc,
        "current_accuracy_pct":       metrics.get("accuracy_pct"),
        "trend":                      ("improving" if float(metrics.get("accuracy_pct",70)) > hv_acc
                                        else "stable" if abs(float(metrics.get("accuracy_pct",70))-hv_acc)<5
                                        else "declining"),
    }

    # Widget 8: Overall Score
    w_overall = {
        "overall_accuracy_score": scorecard.get("overall_accuracy_score"),
        "all_targets_met":        scorecard.get("all_targets_met"),
        "targets_met":            scorecard.get("targets_met",{}),
        "weights":                scorecard.get("weights",{}),
    }

    # Dashboard status
    overall_score = float(scorecard.get("overall_accuracy_score",70))
    dash_status   = ("TARGET_MET"  if scorecard.get("all_targets_met") else
                     "APPROACHING" if overall_score >= 75 else "BELOW_TARGET")

    return {
        "grdf_version":  "ACCURACY_V1",
        "date":          TODAY,
        "generated_at":  now_ts,
        "dashboard_status": dash_status,
        "overall_score": overall_score,
        "prediction_registry": w_registry,
        "hit_rate":            w_hitrate,
        "calibration":         w_calibration,
        "domain_accuracy":     w_domains,
        "country_accuracy":    w_countries,
        "forecast_horizons":   w_horizons,
        "accuracy_trends":     w_trends,
        "overall_score_widget":w_overall,
    }


# ── Accuracy Orchestrator ─────────────────────────────────────────────────

def save_grdf_accuracy(snapshots: list) -> None:
    """
    GRDF Real-World Accuracy Program V1.
    Architecture frozen. No new layers. Accuracy measurement only.
    Reads: v1..v13 + all prior programs (read-only).
    Writes: accuracy/* only.

    Success targets:
      Forecast Accuracy   ≥ 70%
      Warning Precision   ≥ 80%
      Calibration Error   ≤ 10%
      Overall Acc Score   ≥ 85
    """
    import time as _tacc
    ACCURACY_DIR.mkdir(parents=True, exist_ok=True)
    t_start = _tacc.monotonic()

    def _save(fname: str, data: dict) -> None:
        with open(ACCURACY_DIR / fname,"w") as f:
            json.dump({**data,"date":TODAY,"generated_at":datetime.now(timezone.utc).isoformat()},
                      f, ensure_ascii=False, indent=2)

    print("[ACCURACY] Real-World Accuracy Program V1 — Architecture frozen", file=sys.stderr)

    # Phase 1
    pred_reg = _build_acc_prediction_registry(snapshots)
    _save("prediction_registry.json", pred_reg)
    print(f"[ACCURACY] Phase 1: {pred_reg['total_predictions']} predictions registered", file=sys.stderr)

    # Phase 2
    outcome_reg = _build_acc_outcome_registry(snapshots)
    _save("outcome_registry.json", outcome_reg)
    print(f"[ACCURACY] Phase 2: {outcome_reg['total_outcomes']} outcomes registered elevated={outcome_reg['elevated_n']}", file=sys.stderr)

    # Phase 3
    matching = _build_acc_matching(pred_reg, outcome_reg)
    _save("prediction_matching.json", matching)
    print(f"[ACCURACY] Phase 3: hit_rate={matching['hit_rate_pct']}% hits={matching['hit_n']}/{matching['matched_n']}", file=sys.stderr)

    # Phase 4
    metrics = _build_acc_metrics(matching, pred_reg)
    _save("accuracy_metrics.json", metrics)
    print(f"[ACCURACY] Phase 4: accuracy={metrics['accuracy_pct']}% P={metrics['precision']} F1={metrics['f1_score']} cal_err={metrics['calibration_error_pct']}%", file=sys.stderr)

    # Phase 5
    horizon_a = _build_acc_horizon_accuracy(matching, pred_reg)
    _save("horizon_accuracy.json", horizon_a)
    print(f"[ACCURACY] Phase 5: best_horizon={horizon_a['best_horizon']} tested={len(horizon_a['horizons_tested'])}", file=sys.stderr)

    # Phase 6
    calibration = _build_acc_confidence_calibration(matching, pred_reg)
    _save("confidence_calibration.json", calibration)
    print(f"[ACCURACY] Phase 6: cal_error={calibration['mean_calibration_error_pct']}% target_met={calibration['target_met']}", file=sys.stderr)

    # Phase 7
    domain_a = _build_acc_domain_accuracy(matching, pred_reg, snapshots)
    _save("domain_accuracy.json", domain_a)
    print(f"[ACCURACY] Phase 7: best={domain_a['best_domain']} worst={domain_a['worst_domain']}", file=sys.stderr)

    # Phase 8
    country_a = _build_acc_country_accuracy(matching, pred_reg)
    _save("country_accuracy.json", country_a)
    print(f"[ACCURACY] Phase 8: {country_a['total_countries']} countries avg_acc={country_a['avg_accuracy_pct']}%", file=sys.stderr)

    # Phase 9
    lo_warn = _acc_load_dir("live_operations","live_warning_metrics.json")
    scorecard = _build_acc_scorecard(metrics, lo_warn, horizon_a, calibration, domain_a, snapshots)
    _save("accuracy_scorecard.json", scorecard)
    print(f"[ACCURACY] Phase 9: overall={scorecard['overall_accuracy_score']} all_targets={scorecard['all_targets_met']}", file=sys.stderr)

    # Phase 10
    dashboard = _build_acc_dashboard(pred_reg, outcome_reg, matching, metrics,
                                      horizon_a, calibration, domain_a, country_a, scorecard)
    _save("accuracy_dashboard.json", dashboard)

    elapsed = round((_tacc.monotonic()-t_start)*1000)
    print(f"[ACCURACY] Phase 10: status={dashboard['dashboard_status']} score={dashboard['overall_score']} ({elapsed}ms)", file=sys.stderr)

    # Target summary
    t = scorecard["targets_met"]
    print(f"[ACCURACY] TARGETS: forecast≥70={'OK' if t.get('forecast_accuracy_gte_70') else 'MISS'} "
          f"precision≥0.80={'OK' if t.get('warning_precision_gte_80') else 'MISS'} "
          f"cal≤10={'OK' if t.get('calibration_error_lte_10') else 'MISS'} "
          f"overall≥85={'OK' if t.get('overall_score_gte_85') else 'MISS'}", file=sys.stderr)


