# ── Launch Sprint Orchestrator ────────────────────────────────────────────

def save_grdf_launch_sprint(snapshots: list) -> None:
    """
    GRDF Launch Sprint V1 — Risk Map V1 Completion.
    Target: Archive + Signal Pro launch June 9–11, 2026.
    STRATEGIC PRO and ELITE deferred to post-launch.
    Writes: launch/* only. Architecture frozen at V13.
    """
    import time as _tls
    LAUNCH_SPRINT_DIR.mkdir(parents=True, exist_ok=True)
    t_start = _tls.monotonic()

    def _save(fname: str, data: dict) -> None:
        with open(LAUNCH_SPRINT_DIR / fname,"w") as f:
            json.dump({**data,"date":TODAY,"generated_at":datetime.now(timezone.utc).isoformat()},
                      f, ensure_ascii=False, indent=2)

    print(f"[LAUNCH] Launch Sprint V1 — Platform READY {_PLATFORM_READY} · Sales {_SALES_OPEN} · Launch {_LAUNCH_DATE}", file=sys.stderr)

    sprint   = _build_launch_sprint(snapshots)
    _save("launch_sprint.json", sprint)
    print(f"[LAUNCH] Sprint: tasks={sprint['total_tasks']} critical={sprint['critical_n']} areas={len(sprint['area_breakdown'])}", file=sys.stderr)

    readiness= _build_launch_readiness(snapshots)
    _save("launch_readiness.json", readiness)
    print(f"[LAUNCH] Readiness: {readiness['ready_n']}/{readiness['total_components']} ready ({readiness['readiness_pct']}%)", file=sys.stderr)

    journey  = _build_launch_user_journey()
    _save("launch_user_journey.json", journey)
    print(f"[LAUNCH] Journey: {journey['total_steps']} steps, conversion at step {journey['conversion_step']}", file=sys.stderr)

    api_audit= _build_launch_api_audit()
    _save("launch_api_audit.json", api_audit)
    print(f"[LAUNCH] API: {api_audit['total_routes']} routes ready ({api_audit['free_routes_n']} FREE + {api_audit['paid_routes_n']} paid)", file=sys.stderr)

    model    = _build_launch_commercial_model()
    _save("launch_commercial_model.json", model)

    elapsed  = round((_tls.monotonic()-t_start)*1000)
    print(f"[LAUNCH] Model: FREE + SIGNAL PRO active · STRATEGIC/ELITE deferred ({elapsed}ms)", file=sys.stderr)
    print(f"[LAUNCH] ══ PLATFORM READY · Technical {readiness['technical_readiness_pct']}% · Sales Open {_SALES_OPEN} · Official Launch {_LAUNCH_DATE} ══", file=sys.stderr)


def main():
    print(f"\n=== Country Snapshot Engine MVP V1 ===", file=sys.stderr)
    print(f"Date: {TODAY}  Countries: {len(COUNTRIES)}", file=sys.stderr)

    events = load_events()
    _persist_tagged_events(events)
    if not events:
        print("[SNAP] No events — using baselines for all countries", file=sys.stderr)

    snapshots = []
    for iso2 in COUNTRIES:
        try:
            snap = build_snapshot(iso2, events)
            snapshots.append(snap)
            update_history(snap)
        except Exception as e:
            print(f"  [SNAP] {iso2}: FAILED — {e}", file=sys.stderr)
            import traceback
            traceback.print_exc(file=sys.stderr)

    save_daily(snapshots)
    update_index(snapshots)
    generate_intelligence_feed(snapshots)
    generate_global_alerts(snapshots)
    save_country_timelines(snapshots)
    save_country_scenarios(snapshots)
    # ── LEAK-4 FIX: Wire engine unique outputs into snap for Scenario Engine ──
    # Attaches _systemic_pressure, _signal_velocity, _readiness_score,
    # _resilience_score, _cascade_probability to each snap dict so that
    # generate_scenarios uses real values instead of score×k fallbacks.
    for snap in snapshots:
        iso2 = snap["country"]
        try:
            sys_data  = compute_systemic_risk(snap)
            ew_data   = compute_early_warning(snap)
            ds_data   = compute_decision_support(snap)
            res_data  = compute_resilience(snap)
            snap["_systemic_pressure"]  = sys_data.get("systemic_pressure", 0)
            snap["_signal_velocity"]    = ew_data.get("signal_velocity", 0)
            snap["_readiness_score"]    = ds_data.get("readiness_score", 0)
            snap["_resilience_score"]   = res_data.get("resilience_score", 50)
            # cascade_probability: max from active combos
            combos = sys_data.get("active_combos", [])
            snap["_cascade_probability"] = max(
                (c.get("cascade_probability", 0) for c in combos), default=0
            )
        except Exception as e:
            import sys as _sys
            print(f"  [WIRE] {iso2}: {e}", file=_sys.stderr)
    save_country_correlations(snapshots)
    save_propagation(snapshots)
    save_systemic(snapshots)
    save_early_warning(snapshots)
    save_decision_support(snapshots)
    save_resilience(snapshots)
    save_calibration(snapshots)
    save_strategy(snapshots)
    save_strategy_feedback(snapshots)
    save_validation(snapshots)
    save_dashboard(snapshots)
    save_decision_quality(snapshots)
    save_strategy_optimization(snapshots)
    save_recommendations(snapshots)
    save_scenario_evolution(snapshots)
    save_global_risk_intelligence(snapshots)
    save_external_validation()
    save_track_record(snapshots)
    save_explainability()
    save_alerts()
    save_alert_rankings(snapshots)
    save_grdf(snapshots)
    save_grdf_v2(snapshots)
    save_grdf_v3(snapshots)
    save_grdf_v4(snapshots)
    save_grdf_v5(snapshots)
    save_grdf_v6(snapshots)
    save_grdf_v7(snapshots)
    save_grdf_v8(snapshots)
    save_grdf_v9(snapshots)
    save_grdf_v10(snapshots)
    save_grdf_v11(snapshots)
    save_grdf_v12(snapshots)
    save_grdf_v13(snapshots)
    save_grdf_hardening(snapshots)
    save_grdf_production(snapshots)
    save_grdf_final_certification(snapshots)
    save_grdf_baseline(snapshots)
    save_grdf_change_control(snapshots)
    save_grdf_historical_validation(snapshots)
    save_grdf_live_operations(snapshots)
    save_grdf_accuracy(snapshots)
    save_grdf_improvement(snapshots)
    save_grdf_governance(snapshots)
    save_grdf_operations(snapshots)
    save_grdf_impact(snapshots)
    save_grdf_sustainability(snapshots)
    save_grdf_feed(snapshots)
    save_grdf_ews(snapshots)
    save_grdf_commercial(snapshots)
    save_grdf_mobile_ux_audit(snapshots)
    save_grdf_country_intel(snapshots)
    save_grdf_launch_sprint(snapshots)
    save_grdf_alert_map_v2(snapshots)
    save_grdf_command(snapshots)

    scores = [s["risk_score"] for s in snapshots]
    print(
        f"\n[SNAP] Done: {len(snapshots)}/{len(COUNTRIES)} countries "
        f"avg_score={sum(scores)//len(scores) if scores else 0}",
        file=sys.stderr
    )


if __name__ == "__main__":
    main()